	[321011048] = {
		speaker = "「医生」",
		prefab_name = "",
		content = "是吗……不好意思，我确实不太了解加尔的环境。",
		id = 321011048
	},
	[321011049] = {
		speaker = "「医生」",
		prefab_name = "",
		content = "刚才你说你还有一位姐姐，一般这种话题在亲人之间会比较合适。你和你姐姐的关系不好吗？",
		id = 321011049
	},
	[321011050] = {
