		id = 321011063
	},
	[321011064] = {
		speaker = "「医生」",
		prefab_name = "",
		content = "他刚来基维塔巴不久，认识他的人不多，所以预约没那么紧张。",
		id = 321011064
	},
	[321011065] = {
