	[321102031] = {
		speaker = "",
		prefab_name = "",
		content = "奥西里斯回头看了一眼，身后确实没人，这才抱着镰刀停下来。伽梨拍着胸口，随便挑了个路墩子坐下。",
		id = 321102031
	},
	[321102032] = {
		speaker = "",
		prefab_name = "",
		content = "街边躺着不少昏迷的人，但已经没人有精力管他们了。往日车水马龙的主城区街道，现在却比最偏远的郊区还要冷清。",
		id = 321102032
	},
	[321102033] = {
		speaker = "",
		prefab_name = "",
		content = "就像是所有针对视骸或者一般性灾害的社会系统全部没了响应，很难想象这座城市究竟发生了什么。",
		id = 321102033
	},
	[321102034] = {
		speaker = "伽梨",
		prefab_name = "1156ui_story",
		content = "这些人都怎么了？看上去没受伤，也没被骸能侵蚀，为什么忽然全都晕过去了？",
