	[321102039] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "也许吧……但如果是这样，被抽走的算力去哪儿了？",
		id = 321102039
	},
	[321102040] = {
		speaker = "",
		prefab_name = "",
		content = "想不出眉目，奥西里斯叹了口气，思绪从纷乱的线索里面抽出来，这才注意到伽梨的双臂正止不住地发抖。",
		id = 321102040
