	[321102107] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "伊里伽尔姐姐回来了吗？",
		id = 321102107
	},
	[321102108] = {
		speaker = "",
		prefab_name = "",
		content = "奈奈没有回答诗蔻蒂，从窗户缝里钻了出去。诗蔻蒂急忙跑出去追，围着房子绕了一圈，看到奈奈从东侧的围墙翻了出去。",
		id = 321102108
	},
	[321102109] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "啊，奈奈，不可以乱跑。",
		id = 321102109
	},
	[321102110] = {
		speaker = "",
		prefab_name = "",
		content = "挂在围墙上的监控探头跟随着诗蔻蒂的身影，直到她从东侧的小门离开。",
		id = 321102110
	},
	[321102111] = {
		speaker = "",
		prefab_name = "",
		content = "但此时已经没有人盯着监控了，也没有人在东门附近。几乎所有人都聚在园区的西侧和南侧——西边是撤离的方向，南边则是训练场。",
		id = 321102111
	},
	[321102112] = {
		speaker = "",
		prefab_name = "",
		content = "至于东边……那是主城区的方向。",
		id = 321102112
	},
	[321111001] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "北方向五十米。上面应该是一所小学。",
		id = 321111001
	},
	[321111002] = {
		speaker = "",
		prefab_name = "",
		content = "视骸被无形的利刃肢解，化作游离的骸能，涅赫贝特若无其事地抬头看了看，在地图上又描了一段我们走过的路线。",
		id = 321111002
	},
	[321111003] = {
		speaker = "",
		prefab_name = "",
		content = "从巴钦脱困开始，我们两个已经结伴在地下走了将近一千米。途中到处都是严重的塌方，以及时不时游荡到我们面前的视骸。",
		id = 321111003
	},
	[321111004] = {
		speaker = "",
		prefab_name = "",
		content = "在这样足够近的距离上，我终于看清了涅赫贝特的「武器」。",
		id = 321111004
	},
	[321111005] = {
		speaker = "我",
		prefab_name = "",
		content = "你手里拿的……是科尔盖的制式匕首吗？",
		id = 321111005
	},
	[321111006] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "是。怎么了？",
		id = 321111006
	},
	[321111007] = {
		speaker = "我",
		prefab_name = "",
		content = "你权钥呢？",
		id = 321111007
	},
	[321111008] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "没必要。",
		id = 321111008
	},
	[321111009] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "对付普通视骸，一把匕首就够了。遇到智骸，权钥不如「锁」那样的对策武器。",
		id = 321111009
	},
	[321111010] = {
		speaker = "我",
		prefab_name = "",
		content = "刚才确实压制住他了……可惜。",
		id = 321111010
	},
	[321111011] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "「可惜」吗？我不觉得这是意外，也没什么好可惜的。",
		id = 321111011
	},
	[321111012] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "联合仲裁再怎么吝啬也不会在这种规模的地下工程上偷工减料，对自然灾害的防护一定会做到极致。",
		id = 321111012
	},
	[321111013] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "以地震的标准来说，刚才的震动并不算特别强，但管道却出现了大规模毁坏。这说明什么？",
		id = 321111013
	},
	[321111014] = {
		speaker = "我",
		prefab_name = "",
		content = "震源直接连接着管道结构。",
		id = 321111014
	},
	[321111015] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "对，所以相比于出去，先找到震源更重要，否则随时可能再来一次。",
		id = 321111015
	},
	[321111016] = {
		speaker = "",
		prefab_name = "",
		content = "我点点头，跟在她身后，一边警惕着周围的环境，一边留意着弥弥尔系统读取到的各项数据。",
		id = 321111016
	},
	[321111017] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "岔路，哪边？",
		id = 321111017
	},
	[321111018] = {
		speaker = "我",
		prefab_name = "",
		content = "左边，捕捉到一条比较稳定的声波频率，匹配到几台大型机械设备。",
		id = 321111018
	},
	[321111019] = {
		speaker = "",
		prefab_name = "",
		content = "没有片刻迟疑，涅赫贝特先走进左边的岔道。我有些意外地看着她，她也若有所觉地回头看了我一眼。",
		id = 321111019
	},
	[321111020] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "信任是相互的。你同意和我一起在地下调查，我就没有理由怀疑你的判断。",
		id = 321111020
	},
	[321111021] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "虽然就我对你的了解，你做出这样的选择似乎有些奇怪。",
		id = 321111021
	},
	[321111022] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "档案上说你是个重感情的人。但你看起来并不担心你的同伴。",
		id = 321111022
	},
	[321111023] = {
		speaker = "我",
		prefab_name = "",
		content = "地上的事有地上的人管，怎么看都是我们的处境更糟糕吧……",
		id = 321111023
	},
	[321111024] = {
		speaker = "我",
		prefab_name = "",
		content = "奥西里斯有伽梨陪着，两个人都很机灵，应该不会出问题。",
		id = 321111024
	},
	[321111025] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "我说的是薇儿丹蒂。智骸似乎一直对她很感兴趣。",
		id = 321111025
	},
	[321111026] = {
		speaker = "我",
		prefab_name = "",
		content = "她啊……",
		id = 321111026
	},
	[321111027] = {
		speaker = "我",
		prefab_name = "",
		content = "相信我，如果她和巴钦打起来，我们会知道的。",
		id = 321111027
	},
	[321111028] = {
		speaker = "",
		prefab_name = "",
		content = "耀眼的金芒从土石的缝隙中迸溅，紧接着在沉闷的碎裂声中炸开一个人高的洞口。",
		id = 321111028
	},
	[321111029] = {
		speaker = "",
		prefab_name = "",
		content = "一道人影趁着灰尘的掩护钻出来，举着剑左右来回看了好几遍，确认没有其他会活动的东西，才慢慢将剑垂低。",
		id = 321111029
	},
	[321111030] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "这里也没人……是往不同的方向走了吗？",
		id = 321111030
	},
	[321111031] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "我记得管理员被涅赫贝特主任拉到反方向，应该走不到这里。但是其他人也没遇到……",
		id = 321111031
	},
	[321111032] = {
		speaker = "",
		prefab_name = "",
		content = "回想巴钦脱困时的情景，坠落和坍塌确实将在场的修正者与士兵分隔到几个不同的区域，但下水道的路线并没有复杂到能让这么多人一直往前走而互不相遇。",
		id = 321111032
	},
	[321111033] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "难道都已经出去了吗？！",
		id = 321111033
	},
	[321111034] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "对啊，我为什么要待在地下？",
		id = 321111034
	},
	[321111035] = {
		speaker = "",
		prefab_name = "",
		content = "先是因为自己的惊世发现而欣喜，又很快反应过来这好像是再简单不过的道理，薇儿丧气地低了低头，接着往前走。",
		id = 321111035
	},
	[321111036] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "……嗯？",
		id = 321111036
	},
	[321111037] = {
		speaker = "",
		prefab_name = "",
		content = "可还没走出几步，她就看到前方的地上横七竖八躺着不少科尔盖士兵。他们身上没有任何伤口，武器散落在地上，四周也没有交战的痕迹。",
		id = 321111037
	},
	[321111038] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "你们怎么了？能听见我说话吗？",
		id = 321111038
	},
	[321111039] = {
		speaker = "",
		prefab_name = "",
		content = "晃了晃几个人的身体，全都没有动静。薇儿犹豫了一下，摘掉其中一个人的头盔。",
		id = 321111039
	},
	[321111040] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "！！",
		id = 321111040
	},
	[321111041] = {
		speaker = "",
		prefab_name = "",
		content = "头盔下的脸庞没有任何异状，甚至还睁着眼睛，但已经没有了没有呼吸和心跳，仿佛全身都凝滞了一般。",
		id = 321111041
	},
	[321111042] = {
		speaker = "",
		prefab_name = "",
		content = "薇儿连忙站起身环视四周，晦暗的灯光让走道尽头的黑暗看上去更加幽深。她努力感应着黑暗深处的响动，居然真的感应到了一股隐晦又庞大的骸能存在。",
		id = 321111042
	},
	[321111043] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "果然是视骸吗？！",
		id = 321111043
	},
	[321111044] = {
		speaker = "",
		prefab_name = "",
		content = "用最快的速度将这些状态不明的士兵们拖到角落里藏好，薇儿提着剑朝感应到骸能的方向跑去。",
		id = 321111044
	},
	[321112001] = {
		speaker = "",
		prefab_name = "",
		content = "突然遇到巴钦，薇儿打了个哆嗦，好在两人之间的距离似乎还不足以让任何一方突然发动攻击，巴钦好像也没有靠近的意思。",
		id = 321112001
	},
	[321112002] = {
		speaker = "",
		prefab_name = "",
		content = "于是薇儿的注意力很快被巴钦周围的景象吸引住了。这方骸能封锁的区域深处是一片仿佛星河般错乱的空间。",
		id = 321112002
	},
	[321112003] = {
		speaker = "",
		prefab_name = "",
		content = "无数淡白色光点飘浮簇拥着中心的圆球，薇儿能感觉到体内两股势同水火的力量都对这些萤火般的光点产生了某种像是接纳的亲和。",
		id = 321112003
	},
	[321112004] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "不用紧张。如你所见，我现在的任务是镇守这个地方。",
		id = 321112004
	},
	[321112005] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "只要你不做出破坏这里的行为，我不会对你动武。",
		id = 321112005
	},
	[321112006] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "我凭什么相信你？",
		id = 321112006
	},
	[321112007] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "夏什瓦特这一场，胜负并不在我们。无意义的争斗，不符合骑士的信条。",
		id = 321112007
	},
	[321112008] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "你不需要相信我。如果你想离开，请便。",
		id = 321112008
	},
	[321112009] = {
		speaker = "",
		prefab_name = "",
		content = "虽然是敌对关系，但巴钦的一言一行都透露着某种不加掩饰的坦诚。薇儿听到巴钦的许诺，都忍不住往后退了一步。",
		id = 321112009
	},
	[321112010] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "（不对不对，我不就是来调查的吗？都找到巴钦和这个可疑的地方了，怎么能现在逃跑？）",
		id = 321112010
	},
	[321112011] = {
		speaker = "",
		prefab_name = "",
		content = "终于想通了自己的目的，薇儿没有再退出第二步，就这么站在一个完全不像对话、甚至不能说是对峙的距离上，警觉地盯着巴钦。",
		id = 321112011
	},
	[321112012] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "你偷袭奥西里斯，就不算「无意义的争斗」了吗？",
		id = 321112012
	},
	[321112013] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "我的目标是冥王，她身上有图灵大人需要的东西。",
		id = 321112013
	},
	[321112014] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "什么东西？",
		id = 321112014
	},
	[321112015] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "执行任务，我不会多问。",
		id = 321112015
	},
	[321112016] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "你……这也太没主见了，图灵让你干什么你就干什么。",
		id = 321112016
	},
	[321112017] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "既然选择追随，就没有理由质疑。",
		id = 321112017
	},
	[321112018] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "图灵大人的想法非常纯粹，我和他有共同的疑问和观念，足够了。",
		id = 321112018
	},
	[321112019] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "你们的想法，就是复活天灾种吗？",
		id = 321112019
	},
	[321112020] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "……奥蒂斯果然背叛了。人类，终归是人类。",
		id = 321112020
	},
	[321112021] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "那我就当你承认了。天灾种……",
		id = 321112021
	},
	[321112022] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "你们到底想干什么？杀那么多人，把盖亚毁掉，目的到底是什么？",
		id = 321112022
	},
	[321112023] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "前提有误。「杀死人类」和「毁灭盖亚」不是我们要做的事。",
		id = 321112023
	},
	[321112024] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "修正者、人类、原质区、盖亚的各种系统……太多阻拦我们的东西，只能视作敌人，并且清除。",
		id = 321112024
	},
	[321112025] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "我曾思考过，并同时抱有这样的想象——修正者、人类与我们，是否可以为了共同的目的合作。",
		id = 321112025
	},
	[321112026] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "因为我们以同样的方式思考，使用相同的语言，居住在同一个世界，这本可以成为走向共存的基础。",
		id = 321112026
	},
	[321112027] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "可惜，当启示降临的时候，芥蒂已深，两个族群都为各自存续无暇他顾，个体的想法改变不了大势。",
		id = 321112027
	},
	[321112028] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "所以，图灵大人，以及你，特殊的存在弥足珍贵。",
		id = 321112028
	},
	[321112029] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "……感觉你想多了，没什么特殊的。",
		id = 321112029
	},
	[321112030] = {
		speaker = "巴钦",
		prefab_name = "10130ui_story",
		content = "是吗？",
		id = 321112030
	},
	[321112031] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "图灵不会把自己当成修正者，我也不会把自己当成视骸。有这样的想法，不就足够了吗？",
		id = 321112031
	},
	[321112032] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "就像你说的，如果可以早点沟通，你们能管好视骸不要攻击人类，也许大家真的可以和平相处。",
		id = 321112032
	},
	[321112033] = {
		speaker = "薇儿丹蒂",
		prefab_name = "1284ui_story",
		content = "毕竟，我想，没有人不喜欢和平，和平的时候才可以做自己喜欢做的事，除非是天生喜欢做坏事……",
