	},
	[321161052] = {
		speaker = "",
		prefab_name = "",
		content = "跟随萨穆雅带领的小队回到地面上，时间已经来到了第二天凌晨，但被诡异红光覆盖的天空完全没有了时间的痕迹，城市光鲜的死寂更让人感到无比压抑。",
		id = 321161052
	},
	[321161053] = {
