		prefab_name = "",
		content = "……这就没了？具体的呢？",
		id = 321191074
	},
	[321191075] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "这种不算吗？那达克纳先生有吗？",
		id = 321191075
	},
	[321191076] = {
		speaker = "达克纳",
		prefab_name = "",
		content = "呃，怎么反过来问我。",
