	},
	[321252030] = {
		speaker = "我",
		prefab_name = "",
		content = "这是刚才我接触到枢纽核心的时候发现的……按枢纽核心的工作模式，所谓的复活，准确地说应该是「复制」。",
		id = 321252030
	},
	[321252031] = {
