		id = 321252036
	},
	[321252037] = {
		speaker = "",
		prefab_name = "",
		content = "「你了解蛇这种生物吗？它们狡诈、贪婪、阴险……极少直接参与撕咬，而是靠着诡计诱捕猎物。」",
