	[418051016] = {
		speaker = "禄良",
		prefab_name = "",
		content = "先存异，再求同。虚恒那么大，咱也不敢说对每个地方的喜好都一清二楚，但商场是勇敢者的游戏，你先跨出那一步，才知道有没有赚钱的机会。",
		id = 418051016
	},
	[418051017] = {
		speaker = "安海",
		prefab_name = "",
		content = "嗯……话虽然没错，可毕竟「巡船节」还有我们本地的商品，会不会有些喧客夺主？",
		id = 418051017
	},
	[418051018] = {
