	},
	[418061003] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "科尔盖到的时候，视骸已经被姐姐给搞定啦。我后来又回去过一趟，工坊主们现在过得都还不错呢，慕名去旅游的人也多起来了。",
		id = 418061003
	},
	[418061004] = {
		speaker = "禄良",
		prefab_name = "",
		content = "哈哈，好事儿，咱们天禄贸易的目标，就是让大家都能赚钱嘛。",
		id = 418061004
	},
	[418061005] = {
		speaker = "禄良",
