	},
	[418061010] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "无缘无故也会受到骸能污染吗？",
		id = 418061010
	},
	[418061011] = {
		speaker = "禄良",
		prefab_name = "",
		content = "哈哈，那可不一定是「无缘无故」。先帮咱把这些小家伙制止住吧，等会儿咱再跟你慢慢说~",
		id = 418061011
	},
	[418061012] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "嗯！",
		id = 418061012
	},
	[418062001] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "禄良前辈，这些智械怎么回事……为什么会突然攻击我们？",
		id = 418062001
	},
	[418062002] = {
		speaker = "禄良",
		prefab_name = "",
		content = "你觉得呢？「风大浪大」，难保智械里面不会进水。",
