	[418062003] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "水？这里哪……你是说骸能？",
		id = 418062003
	},
	[418062004] = {
		speaker = "禄良",
		prefab_name = "",
		content = "嗯哼。这种事倒是不罕见，毕竟海中的视骸活动更隐蔽一些，偷偷摸上岸搞破坏也算是常事。咱们天禄贸易在虚恒各地安排货运点，也有这一层考虑。",
		id = 418062004
	},
	[418062005] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "原来是这样……",
		id = 418062005
	},
	[418062006] = {
		speaker = "麟钰",
		prefab_name = "",
		content = "啊……等我看下「定海仪」的监测数据。",
		id = 418062006
	},
	[418062007] = {
		speaker = "禄良",
