		id = 321321012
	},
	[321321013] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "不管是从安全还是效率的角度考虑，我都不建议人类继续深入了。",
		id = 321321013
	},
	[321321014] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "卢克，地面区域的布防警戒交给你们骸震对策部。",
		id = 321321014
	},
	[321321015] = {
		speaker = "卢克",
		prefab_name = "",
		content = "明白。",
		id = 321321015
	},
	[321321016] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "杰森，你带防卫科的人封锁下水道外围，按高危泄漏物的规格做好防范。",
