	},
	[321331013] = {
		speaker = "",
		prefab_name = "",
		content = "罗波那活动着手指上的骨节，迈着沉重的脚步逼近。地面在他的重踏下碎裂，蛛网状的裂痕也随之爬向奥西里斯。",
		id = 321331013
	},
	[321331014] = {
		speaker = "罗波那",
		prefab_name = "",
		content = "做梦呢。都以为自己是猎人，想来拿老子的人头？到底要怎么才会明白，你们才是猎物。",
		id = 321331014
	},
	[321331015] = {
