	},
	[1109506079] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "嗯……",
		id = 1109506079
	},
	[1109506080] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯……",
		id = 1109506080
	},
	[1109506081] = {
		speaker = "",
		prefab_name = "",
		content = "互相认错后，我们站在原地面面相觑，陷入了沉默之中。",
		id = 1109506081
	},
	[1109506082] = {
