	},
	[1109506099] = {
		speaker = "我",
		prefab_name = "",
		content = "那也许主人公觉得旅馆很普通、在公园错过了花展、看小鹿扑了空，各种事情……可能也被「留白」了吧。",
		id = 1109506099
	},
	[1109506100] = {
