	},
	[1109506101] = {
		speaker = "托特",
		prefab_name = "10058ui_story",
		content = "作品的表达都是选择性的，呈现在读者面前的只是「节选」，创作者要做的，应该是从无趣的事件里挑选出人们爱看的情节。",
		id = 1109506101
	},
	[1109506102] = {
