	},
	[1109506107] = {
		speaker = "我",
		prefab_name = "",
		content = "要知道，读者是除了作者之外，最相信你笔下的世界的人。他们会相信你的每个文字都是真诚的，而不是加以修饰的结果。",
		id = 1109506107
	},
	[1109506108] = {
