	},
	[423081002] = {
		speaker = "",
		prefab_name = "",
		content = "在埃什追着匪帮们冲入街道的同时，火车站的一个角落里，劳伦·莱特正惬意地坐在遮阳棚下，将整张脸全部埋进汉堡、炸鸡与可乐组成的小山中。",
		id = 423081002
	},
	[423081003] = {
