	},
	[423081027] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "噢？那究竟是差在哪里，被你发现破绽了呢？",
		id = 423081027
	},
	[423081028] = {
		speaker = "",
		prefab_name = "",
		content = "见到市长进入车厢后就开始左顾右盼，拉格眯起眼，语气温柔的同时，手也摸到了腰后别着的电击枪上。",
		id = 423081028
	},
	[423081029] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
