		id = 423081029
	},
	[423081030] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "看看你的台面，连食物成品都没摆出来！没有视觉冲击，怎么能吸引食客？",
		id = 423081030
	},
	[423081031] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "还有你的灶台，怎么就只有这么点食材？接待我一个客人是够了，如果全镇的人都来排队呢？",
		id = 423081031
	},
	[423081032] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
