	},
	[423081038] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "时不我待，哪有慢慢来的工夫？当然是给车边的工人们都提供一份折扣快餐啊，这是多大的市场！",
		id = 423081038
	},
	[423081039] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "薄利多销懂不懂？到时候我们把快餐带给他们，既给目标人群提供了关心和亲切感，又做了生意，不是双赢？",
		id = 423081039
	},
	[423081040] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "你开车过去吧，能少走两步路。厨房就交给我了~",
