	},
	[423081043] = {
		speaker = "",
		prefab_name = "",
		content = "看着全神贯注地开始按着灶台旋钮，却怎么也打不着火的市长，拉格悄悄将车厢的入口关上，嘴角不禁流露出轻松的笑容，狠狠握了下拳头。",
		id = 423081043
	},
	[423081044] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "嘿嘿，目标到手~",
		id = 423081044
	},
	[423081045] = {
		speaker = "我",
		prefab_name = "",
		content = "在中场休息的时候，市长只说她闻到了熟悉的味道，然后人就没了？",
		id = 423081045
	},
	[423081046] = {
		speaker = "",
