	},
	[423081050] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "镇外哪有馆子，再说她也没钱。总不能跟动画片里一样，有人拿鱼竿绑着食物把她钓走了吧？",
		id = 423081050
	},
	[423081051] = {
		speaker = "维修工",
		prefab_name = "",
		content = "你别说，刚才还真过去一辆餐车，好像就停在外面。",
