	},
	[423081052] = {
		speaker = "我&埃克什瓦",
		prefab_name = "",
		content = "餐车？长什么样，在哪里！",
		id = 423081052
	},
	[423081053] = {
		speaker = "维修工",
		prefab_name = "",
		content = "我瞅瞅啊……车站尽头的小点看见没？那车可新了，一看就不是镇上的。",
		id = 423081053
	},
	[423081054] = {
		speaker = "我",
		prefab_name = "",
		content = "糟了，正经生意人谁会停那里！",
		id = 423081054
	},
	[423081055] = {
		speaker = "",
		prefab_name = "",
		content = "顾不得跟工人多说，我和埃什匆匆冲向货车。然而车上的人似乎也察觉到了我们，原本停在原地的货车开始缓慢行驶，车厢侧面也骤然打开，将几个黑黝黝的金属块射向我们。",
		id = 423081055
	},
	[423081056] = {
		speaker = "",
		prefab_name = "",
		content = "巨大的金属块砸在我们的面前，接触到地表的时候外壳就已碎裂。几台从折叠状态复原的智械转眼间就从中弹出，响着刺耳的警报声拦在前方。",
		id = 423081056
	},
	[423081057] = {
		speaker = "武装智械",
		prefab_name = "",
		content = "检测到拦截目标，开始阻击——",
		id = 423081057
	},
	[423082001] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "立刻停下，否则别怪子弹不讲道理！",
		id = 423082001
	},
	[423082002] = {
		speaker = "",
		prefab_name = "",
		content = "匆匆将报废的智械踢到一边，我和埃什全速跑向那辆货车，却依然难以赶上逐渐加速的车辆。埃什掏枪射向车轮，然而子弹却被伸出的裙板挡下，叮叮当当地弹到一边。",
		id = 423082002
	},
	[423082003] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "怎么连车轮都做了防弹，还有这种手段？！",
		id = 423082003
	},
	[423082004] = {
		speaker = "我",
		prefab_name = "",
		content = "有备而来……我们有能追上去的车吗？",
		id = 423082004
	},
	[423082005] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "我摩托还在镇上，现在借车哪来得及。",
		id = 423082005
	},
	[423082006] = {
		speaker = "我",
		prefab_name = "",
		content = "只能试试这个了。给，看能不能先把追踪器射到车上。",
		id = 423082006
	},
	[423082007] = {
		speaker = "",
		prefab_name = "",
		content = "两条腿终究赶不上四个轮子，我们只能眼睁睁地看着货车越开越快。情急之下，我掏出追踪器，一把塞进埃什的枪口，然而没等她开枪，正在疾驰的汽车突然闪过一阵红光。",
		id = 423082007
	},
	[423082008] = {
		speaker = "",
		prefab_name = "",
		content = "就像是平地绊了个趔趄，货车毫无征兆地往空中一跳，随即产生的震动与爆炸顷刻就将我和埃什掀翻。车厢在我们震惊的目光中轰然解体，在电光与浓烟中化为四散的模块。",
		id = 423082008
	},
	[423082009] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "怎么会爆炸！刚才不还是绑架……",
		id = 423082009
	},
	[423082010] = {
		speaker = "我",
