	[423101056] = {
		speaker = "",
		prefab_name = "",
		content = "如火如荼的表演仍在继续，穿着各色服装的匪帮们纵马在街道上肆虐。他们朝空中鸣枪示威，冲过被烟雾笼罩的演讲台，裹着浓郁的烟尘与依稀的呼救声扬长而去，引得观众一阵叫好。",
		id = 423101056
	},
	[423101057] = {
