		id = 423101061
	},
	[423101062] = {
		speaker = "",
		prefab_name = "",
		content = "烟尘一点点从讲台上散去，露出正茫然四顾的埃什。不顾旁边观众与摄影的叫好，我和伊兹尔猛然站起，目瞪口呆地加入了不断张望的埃什。",
		id = 423101062
	},
	[423101063] = {
		speaker = "我&伊兹尔&埃克什瓦",
