	},
	[423101080] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "我警告你们，我们头儿就在镇上。到时候遇到他，没你们好果子吃！",
		id = 423101080
	},
	[423101081] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "那正好把你们一网打尽，省得之后操心了！",
		id = 423101081
