	},
	[423111016] = {
		speaker = "",
		prefab_name = "",
		content = "埃什在宴会上的表现丝毫没有超出我的预期，我又和昨晚一样，与伊兹尔一同将埃什拎了回来。小小的两人间里现在一口气挤了四个人，变得稍微有些炽热起来。",
		id = 423111016
	},
	[423111017] = {
		speaker = "我",
		prefab_name = "",
