		id = 423111054
	},
	[423111055] = {
		speaker = "我",
		prefab_name = "",
		content = "最终我在深空之眼遇到了现在的伙伴们，她们帮我找到了未来的方向和奋斗的意义，也让生活变得充实而幸福。",
		id = 423111055
	},
	[423111056] = {
		speaker = "我",
		prefab_name = "",
		content = "我想把这份感觉带给你，也带给每一个迷茫的修正者。我希望能帮到你们，然后团结力量创造更好的未来。",
		id = 423111056
	},
	[423111057] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "听上去像是修正者领袖会说的话。作为人类，你不会觉得自己有点另类吗？",
