	},
	[423121083] = {
		speaker = "",
		prefab_name = "",
		content = "将通讯切断后，我赶忙把手收回来，边甩着被印上牙印的手心，边看向抱着双臂，一脸不满的埃什。",
		id = 423121083
	},
	[423121084] = {
		speaker = "我",
		prefab_name = "",
		content = "咬就算了，你别用舌头往外顶啊，很痒的。要是谈判的时候笑出来，我该怎么收场？",
		id = 423121084
	},
	[423121085] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "要你管，谁叫你拦着我不让说话，什么意思嘛！",
		id = 423121085
	},
	[423121086] = {
		speaker = "我",
		prefab_name = "",
		content = "你还没反应过来？能开出这种条件，说明她觉得市长还在我们手上。",
		id = 423121086
	},
	[423121087] = {
		speaker = "我",
		prefab_name = "",
		content = "无论是伊兹尔掩护市长逃跑了，或者她提前藏起来了……总之市长现在多半还安全。",
