	[423121092] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "可你不是说她有原则什么的……",
		id = 423121092
	},
	[423121093] = {
		speaker = "我",
		prefab_name = "",
		content = "你愿意拿伊兹尔的性命去冒险？",
		id = 423121093
	},
	[423121094] = {
		speaker = "",
		prefab_name = "",
		content = "原本都打算冲出门的埃什沉默了下来，闷闷地坐回床边。我安慰性地拍了拍她的肩膀，到她身边把我的打算解释了一遍。",
		id = 423121094
	},
	[423121095] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "这有什么区别！你觉得我会愿意拿你的命冒险？",
		id = 423121095
	},
	[423121096] = {
		speaker = "我",
		prefab_name = "",
		content = "某种意义上也是我的日常了……这是相对最稳妥的方案，几乎不包含正面冲突。",
