	[423121097] = {
		speaker = "我",
		prefab_name = "",
		content = "考虑到我的身份，我不觉得拉格真的会下杀手。如果只是花点钱、出点血，那还在可以承担的风险范围内。",
		id = 423121097
	},
	[423121098] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "要不然你去救人，我去当诱饵吸引她对峙……喂，笑什么！",
