		id = 423121100
	},
	[423121101] = {
		speaker = "我",
		prefab_name = "",
		content = "与其担心这个，不如想想计划中还缺失的关键一环。",
		id = 423121101
	},
	[423121102] = {
		speaker = "",
		prefab_name = "",
		content = "向埃什借来她的终端，我一边给镇上的居民们发送着消息，一边整理好随身装备，朝门外走去。",
		id = 423121102
	},
	[423121103] = {
