	},
	[423131005] = {
		speaker = "恰克",
		prefab_name = "",
		content = "知道红石河怎么对待耍机灵的人吗？想空手套白狼的话，就是割掉舌头，如果只是刺探情报，那就切下耳朵。",
		id = 423131005
	},
	[423131006] = {
