	},
	[423131016] = {
		speaker = "",
		prefab_name = "",
		content = "恰克收起刀，自顾自地往外走去。面对拉格的质疑，他只压低了帽檐，随意丢下点回复，便消失在仓库外面。",
		id = 423131016
	},
	[423131017] = {
