	},
	[423131019] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "……随他去吧，免得碍事。\n嗯~比想象中晚一点呢，竟然有这么纠结吗？",
		id = 423131019
	},
	[423131020] = {
		speaker = "",
		prefab_name = "",
		content = "毫不意外地接起通讯，拉格神情自若地听着另一头的阐述，嘴角慢慢勾起，脸上也浮现出一切尽在掌握的自信。",
