	},
	[423181076] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "也可能只是他以修正者的身体素质欺负普通人，传闻嘛。",
		id = 423181076
	},
	[423181077] = {
		speaker = "我",
		prefab_name = "",
		content = "我不觉得埃什和恰克的枪法能差那么多，考虑到他出身于红石河公会，那可能是一把「奇械」。",
		id = 423181077
	},
	[423181078] = {
		speaker = "我",
		prefab_name = "",
		content = "我在想……你能不能把它偷到？",
		id = 423181078
	},
	[423181079] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "只要他带在身上，然后我能靠近的话。但有必要吗？",
		id = 423181079
	},
	[423181080] = {
		speaker = "我",
		prefab_name = "",
		content = "恰克多此一举地非要搞决斗，只能说明他没十足的信心击败埃什，这种方式是他最有胜算的底牌。",
		id = 423181080
	},
	[423181081] = {
		speaker = "我",
		prefab_name = "",
		content = "「奇械」大多超乎常理，保险一点为好。",
		id = 423181081
	},
	[423181082] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么靠近他的话，我记得你很会乔装，那办法就有的是了……",
		id = 423181082
	},
	[423181083] = {
		speaker = "",
		prefab_name = "",
		content = "跟拉格简单商量了下计划后，我查看起终端上传来的消息。有镇民已经发现镇外侦查的匪帮，恐怕进攻很快就要开始。",
		id = 423181083
	},
	[423181084] = {
		speaker = "我",
		prefab_name = "",
		content = "果然还是来了，走吧。",
		id = 423181084
	},
	[423181085] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "埃什呢，不叫她一声？",
