		id = 423191001
	},
	[423191002] = {
		speaker = "",
		prefab_name = "",
		content = "鲜血从匪帮大腿的枪眼上喷涌而出，他当即跪倒在列车的残骸旁边。恰克收回还冒着烟的手枪，冷冷地瞥了一圈噤若寒蝉的众人，朝地上猛啐了一口。",
		id = 423191002
	},
	[423191003] = {
		speaker = "恰克",
		prefab_name = "",
		content = "这么一帮人，解决不了一个小姑娘就算了，还让她开车把人全带走了？",
		id = 423191003
	},
	[423191004] = {
		speaker = "恰克",
		prefab_name = "",
		content = "养条狗都比你们有用，全毙了换下一批算了。",
		id = 423191004
	},
	[423191005] = {
