	},
	[423191009] = {
		speaker = "恰克",
		prefab_name = "",
		content = "看来她也知道东边要经过红石河的地盘，哼，那就在镇上把他们一网打尽好了。",
		id = 423191009
	},
	[423191010] = {
		speaker = "恰克",
		prefab_name = "",
		content = "备车，准备出发。给我把镇子全围起来，一个活口不留。",
