	},
	[423191018] = {
		speaker = "",
		prefab_name = "",
		content = "眼镜仔缩了缩脖子，默默地扶起瘫在地上的鸡冠头，其他人也面面相觑，不敢有更多的意见。",
		id = 423191018
	},
	[423191019] = {
		speaker = "",
		prefab_name = "",
		content = "在沉默的雨中，一行人坐上各式各样的改装车辆，在泥地里掀起滚滚浊浪，轰鸣着扑向长水镇。",
		id = 423191019
	},
	[423191020] = {
