	},
	[423191021] = {
		speaker = "",
		prefab_name = "",
		content = "当我与拉格赶来时，现场的气氛一片凝重。镇子的各处入口已经堆积起拍电影用到的板材与维修火车的零件，将街道拦腰截断。",
		id = 423191021
	},
	[423191022] = {
		speaker = "",
		prefab_name = "",
		content = "不少镇民正在灯光下进行着加固工作，将它们转变成固定在地面的街垒。另外一批人则手持着古旧的枪械，和伊兹尔一同警惕地望向黑暗的荒原。",
		id = 423191022
	},
	[423191023] = {
		speaker = "伊兹尔",
		prefab_name = "",
