	},
	[423191047] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "我有很多想跟你说的，但一时找不到合适的话。你让我好好想想，等一切结束后，我再说给你听。",
		id = 423191047
	},
	[423191048] = {
		speaker = "我",
