	},
	[423191052] = {
		speaker = "餐馆老板",
		prefab_name = "",
		content = "想我们还年轻的时候，不知死活的混混见得太多了，每个月都会闹那么两三回。",
		id = 423191052
	},
	[423191053] = {
		speaker = "旅馆老板",
