	},
	[423191057] = {
		speaker = "餐馆老板",
		prefab_name = "",
		content = "你愿意站出来，你就是。",
		id = 423191057
	},
	[423191058] = {
		speaker = "餐馆老板",
		prefab_name = "",
		content = "如果你不是治安官，那一年来每次都站在我们前面的，能是谁呢？",
		id = 423191058
	},
	[423191059] = {
		speaker = "",
		prefab_name = "",
		content = "埃什怔怔地看着身后的镇民们，脸上的自嘲也收了起来。她和我对视一眼，随后拍了拍胸膛，向人们露出一个自信的笑容。",
		id = 423191059
	},
	[423191060] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "……那就还是老样子，我在前面，你们只要欣赏我的枪法就好。",
		id = 423191060
	},
	[423191061] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "让我们一起把黑夜打碎，见到明天的太阳吧。",
		id = 423191061
	},
	[423191062] = {
		speaker = "",
		prefab_name = "",
		content = "清脆的警钟再度响起，眼下却已不是拍摄电影。大大小小的车灯从荒原的深处浮现，随即在镇外的空地集结。",
		id = 423191062
	},
	[423191063] = {
		speaker = "",
		prefab_name = "",
		content = "沉默的匪帮们汇聚成厚重的阴云，在恰克的带领下从四面八方将长水镇团团围住。然而当他们看到站在入口的埃什时，细碎的流言悄然开始滋生。",
		id = 423191063
	},
	[423191064] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "头儿，那个女的……你不是说把她毙了吗。难道是……怨魂来索命了？",
		id = 423191064
	},
	[423191065] = {
		speaker = "恰克",
		prefab_name = "",
		content = "闭嘴！怎么可能会有那种事，走运逃过一劫罢了。我能杀她一次，也能杀第二次。",
		id = 423191065
	},
	[423191066] = {
		speaker = "恰克",
		prefab_name = "",
		content = "哼，真让人意外，看看是谁站在这里。",
		id = 423191066
	},
	[423191067] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "你没看错，恰克。看来你的必杀绝技也不怎么管用嘛~",
		id = 423191067
	},
	[423191068] = {
		speaker = "恰克",
		prefab_name = "",
		content = "虽然不知道你是怎么活下来的，但你竟然还敢再出现，勇气可嘉。",
		id = 423191068
	},
	[423191069] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "因为你也不过如此。尽管放马过来，我倒要看看你有什么更厉害的手段。",
		id = 423191069
	},
	[423191070] = {
		speaker = "",
		prefab_name = "",
		content = "看着埃什充满自信的神态，恰克皱眉摩挲着腰间的左轮，一时没有轻举妄动。在对峙了片刻之后，他眼珠一转，挥手招来身边的小弟。",
		id = 423191070
	},
	[423191071] = {
		speaker = "恰克",
		prefab_name = "",
		content = "你们先上，试试他们的成色，我去解决其他人。",
		id = 423191071
	},
	[423191072] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "我……我们去除掉她？",
		id = 423191072
	},
	[423191073] = {
		speaker = "恰克",
		prefab_name = "",
		content = "不然让你们带上枪跟炸药是干什么的？她又不是鬼，一样会受伤。",
		id = 423191073
	},
	[423191074] = {
		speaker = "恰克",
		prefab_name = "",
		content = "再说了，有我在后面给你们撑腰，怕什么？",
