	},
	[423191075] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "说得真好听，明明就是拿着枪督战……",
		id = 423191075
	},
	[423191076] = {
		speaker = "恰克",
		prefab_name = "",
		content = "蠢货……她没下杀手的胆子，对付你们也使不出能力，上去消耗一下都不会？",
		id = 423191076
	},
	[423191077] = {
		speaker = "恰克",
		prefab_name = "",
		content = "或者……你们也可以去对付镇民，看他们愿不愿意给你们脑袋开个洞？",
		id = 423191077
	},
	[423191078] = {
		speaker = "",
		prefab_name = "",
		content = "眼镜仔看着一夫当关的埃什，又看了看封锁街道的工事，手微微有些颤抖。他缩了缩脖子，眼角的余光看到恰克脸色越发阴沉，只能硬着头皮挥手，闭着眼睛往前一推。",
		id = 423191078
	},
	[423191079] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "弟兄们，别，别怕！怂也是死，冲也是死！还不如勇敢一点，说不定能缴枪不杀……",
		id = 423191079
	},
	[423191080] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "我是说争取到一丝机会！给我上——",
		id = 423191080
	},
	[423192001] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "又见面了，各位英雄~看到大家都好好的，我真是发自内心地高兴呀~",
		id = 423192001
	},
	[423192002] = {
		speaker = "",
		prefab_name = "",
		content = "又被五花大绑的眼镜仔赔笑着朝我们连连点头，我拧着他的头左右转了转，将目光投向拉格。",
		id = 423192002
	},
	[423192003] = {
		speaker = "我",
		prefab_name = "",
		content = "这面相你看怎么样，能扮吗？",
		id = 423192003
	},
	[423192004] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "……有点嫌弃。\n不过再怎么说我也是专业人士，这种小事……不在话下！",
		id = 423192004
	},
	[423192005] = {
		speaker = "我",
		prefab_name = "",
		content = "委屈你了，否则就算我们能赢，硬拼的代价也会很大。",
		id = 423192005
	},
	[423192006] = {
		speaker = "",
		prefab_name = "",
		content = "我将视线挪向其他街道，尽管镇民们能凭借手中的枪支展开阻击，但在恰克的射击与匪帮们源源不断的重火力压制下，防线还是在一点点被往后逼退。",
		id = 423192006
	},
	[423192007] = {
		speaker = "",
		prefab_name = "",
		content = "长水镇的边缘已燃起火焰，将夜空都烧成一片橙红。匆匆撤下的镇民们多半都挂了彩，被熏黑的脸也难找到哪怕是掩饰性的轻松。",
		id = 423192007
	},
	[423192008] = {
		speaker = "我",
		prefab_name = "",
		content = "擒贼先擒王，我们只能放手一搏了。",
		id = 423192008
	},
	[423192009] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
