		id = 423192009
	},
	[423192010] = {
		speaker = "拉丝格瑞斯",
		prefab_name = "",
		content = "希望那把枪不是他的权钥，否则一切都白搭。",
		id = 423192010
	},
	[423192011] = {
		speaker = "我",
		prefab_name = "",
		content = "总要赌一把，我相信我的判断。",
		id = 423192011
	},
	[423192012] = {
		speaker = "我",
		prefab_name = "",
		content = "接下来，就靠你们了。",
		id = 423192012
	},
	[423192013] = {
		speaker = "",
		prefab_name = "",
		content = "拉格像提小鸡一样把不断求饶的眼镜仔拎走，我望着正逐渐逼近的战线，拍了拍埃什的肩膀。",
		id = 423192013
	},
	[423192014] = {
		speaker = "我",
		prefab_name = "",
		content = "先回餐馆等着吧，我们还有最后一点休整的机会。",
		id = 423192014
	},
	[423192015] = {
