	},
	[423201003] = {
		speaker = "恰克",
		prefab_name = "",
		content = "很好。你们去把它围住，接下来就是一网打尽的时间了。",
		id = 423201003
	},
	[423201004] = {
		speaker = "「眼镜仔」",
		prefab_name = "",
		content = "但他们人还有不少，火力也猛。就这么过去的话，弟兄们损失不小啊？",
