	},
	[423201005] = {
		speaker = "恰克",
		prefab_name = "",
		content = "我让你们去就去！敢不上去的，让他自己来见我。",
		id = 423201005
	},
	[423201006] = {
		speaker = "",
		prefab_name = "",
		content = "瞪了眼仓惶离开的眼镜仔，恰克面色平静地向前走去。爆裂声从他身边的建筑中迸发，窜出的火光将他毫无感情的眼睛照亮。",
		id = 423201006
	},
	[423201007] = {
		speaker = "",
		prefab_name = "",
		content = "他闲庭信步地走过洒满鲜血的街道，走过燃烧的镇子，走入这片冷雨。直至看到黑暗中仅存的文明灯光，他才和手下一同在餐馆外驻足。",
		id = 423201007
	},
	[423201008] = {
		speaker = "恰克",
		prefab_name = "",
		content = "把喷火器和炸药都拿出来，我看他们能藏多久。",
		id = 423201008
	},
	[423201009] = {
		speaker = "「鸡冠头」",
		prefab_name = "",
		content = "头儿，这餐馆边上都是开阔地，过去就是挨枪子啊。要不我们先把他们留下的街垒推过来，慢慢围住……",
		id = 423201009
	},
	[423201010] = {
		speaker = "恰克",
		prefab_name = "",
