	},
	[423201012] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "恰克，我原本以为你还算个人物，没想到只是这么个懦弱的东西啊。",
		id = 423201012
	},
	[423201013] = {
		speaker = "",
		prefab_name = "",
		content = "餐馆的门被猛地推开，埃什持枪站在门口，居高临下地打量着恰克。通明的灯火从她背后射出，一时晃得匪帮们有些睁不开眼。",
		id = 423201013
	},
	[423201014] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "没错，我还好好地活着。既不是幽灵，也不是什么投影。",
