	},
	[423201023] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "这话说出来，恐怕会让你的手下有点寒心啊。跟着你真有前途吗？",
		id = 423201023
	},
	[423201024] = {
		speaker = "恰克",
		prefab_name = "",
		content = "耍嘴皮子倒是厉害。一起上，乱枪把她打死。",
