	},
	[423201027] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "还是说……你所谓「一击必胜」的手段没用之后，就完全没有信心打过任何一个人了？",
		id = 423201027
	},
	[423201028] = {
		speaker = "",
		prefab_name = "",
		content = "恰克转回头，所有被他目光扫视到的匪帮们都因惧怕向后缩了一步。但即便如此，仍然没有匪帮敢率先出头，只是一个个眼神中闪烁着小心思，纷纷开始装鸵鸟。",
		id = 423201028
	},
	[423201029] = {
		speaker = "恰克",
		prefab_name = "",
		content = "想要激我放弃人数优势？算盘打得倒是挺响。",
