	},
	[423201037] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "你最好真有这实力，否则……可就让你的手下看到你的真实水平了。",
		id = 423201037
	},
	[423201038] = {
		speaker = "",
		prefab_name = "",
		content = "恰克的眼神冷下去，无须回头就已经感受到了一道道针扎般的目光。他悄悄地把手伸到腰间，在摸了个空之后，脸色终于起了变化。",
		id = 423201038
	},
	[423201039] = {
		speaker = "恰克",
		prefab_name = "",
		content = "这怎么可能……什么时候？",
		id = 423201039
	},
	[423201040] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "怎么愣住了，准备开始吧。",
		id = 423201040
	},
	[423201041] = {
