	[423202081] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "不过转念一想，镇子随时都能回来看，世界上还有更多人需要帮助，还有滋养出恰克这种毒草的环境需要被铲除。",
		id = 423202081
	},
	[423202082] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "修正者的人生很长，该重新踏上旅途，践行我的价值了。",
		id = 423202082
	},
	[423202083] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "我已经给自己想好新头衔了，「巡回治安官」。怎么样，很不错吧？",
		id = 423202083
	},
	[423202084] = {
		speaker = "",
		prefab_name = "",
		content = "埃什复杂的笑颜映在银星的断面上，每一片闪耀的残片都照出她不同角度的侧脸。她的神情中夹杂了几分落寞，更多的却是释然。",
		id = 423202084
	},
	[423202085] = {
		speaker = "",
		prefab_name = "",
		content = "她用手指在碎片上轻轻摩挲，把它们慢慢拨到一起。将已无法弥合的正义象征拼凑起来后，埃什抬头注视着我，眼睛中仿佛倒映出灿烂的星光。",
		id = 423202085
	},
	[423202086] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "曾经的我在荒原上不知道前进的方向，追逐着头顶的星星，希望能在自由的天空寻找到一席之地。",
		id = 423202086
	},
	[423202087] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "可后来我发现，它只是一个旧日的残影。它远没有我想象中那般光辉，现在也已经坠落。",
		id = 423202087
	},
	[423202088] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "不过……我很庆幸，它落到了会珍视它的人手中。",
		id = 423202088
	},
	[423202089] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "而且他还告诉了我，到底要前往怎样的方向，才能找到我所希望的安身之处。",
		id = 423202089
	},
	[423202090] = {
		speaker = "",
		prefab_name = "",
		content = "埃什轻轻地用手心压着我的手指，将我握住银星的手推到心口。我能清晰地感受到她掌心传来的温度，正如她此时的笑容，炽热而坚定。",
		id = 423202090
	},
	[423202091] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "今后，我可就跟定你了，#{nickname}#。",
		id = 423202091
	},
	[423211001] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "要出发了吗？",
		id = 423211001
	},
	[423211002] = {
		speaker = "",
		prefab_name = "",
		content = "又在长水镇待了几天之后，我最终还是与埃什一同站在了停靠的火车旁。伊兹尔与镇民们一同围在身边，为我们献上了临行的祝福。",
		id = 423211002
	},
	[423211003] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯，多待的这几天已经把事情基本收尾了，我们也该回核心城了。",
		id = 423211003
	},
	[423211004] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "小帽子你真的想好了吗？治安官这工作可不轻松啊。",
		id = 423211004
	},
	[423211005] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "我确实想跟老大一样保护大家嘛，绝对心甘情愿。",
		id = 423211005
	},
	[423211006] = {
		speaker = "",
		prefab_name = "",
		content = "伊兹尔一边说着，一边将一块反射出黄铜色彩的徽章戴在自己胸前。阳光洒在治安官的徽记上闪闪发亮，乍一看还挺像回事。",
		id = 423211006
	},
	[423211007] = {
		speaker = "我",
		prefab_name = "",
		content = "你这又是从哪弄来的，该不会……也是随手捡的？",
		id = 423211007
	},
	[423211008] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "不是啦，用之前战斗里的弹壳熔的。我觉得这是大家一起战斗的象征~",
		id = 423211008
	},
	[423211009] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "要是有人敢挑事，我就用它展示下坏蛋的下场。",
		id = 423211009
	},
	[423211010] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "你啊，还是有这么多鬼点子。以后也要多想想正经办法。",
		id = 423211010
	},
	[423211011] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "还有，别掉以轻心。虽然那群匪帮都入狱了，但恰克还背着通缉在逃。",
		id = 423211011
	},
	[423211012] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "我懂的。不过有你们公司的帮助，我觉得他也不敢过来。",
		id = 423211012
	},
	[423211013] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "那家伙怕死得很，怎么敢自投罗网呢？",
		id = 423211013
	},
	[423211014] = {
		speaker = "我",
		prefab_name = "",
		content = "总之有问题随时联系，从核心城过来没多长时间。我们也会抽空回来看看的。",
		id = 423211014
	},
	[423211015] = {
		speaker = "我",
		prefab_name = "",
		content = "希望在你的带领下，长水镇能成功实现我们所规划的未来。",
		id = 423211015
	},
	[423211016] = {
		speaker = "",
		prefab_name = "",
		content = "我指了指火车站台的另一边，在新树立起的旅游地图与影视乐园宣传页前，劳伦·莱特抱着怀中的皮箱，正对着无数镜头眉飞色舞。",
		id = 423211016
	},
	[423211017] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "在我看来，选择铁路旅游，既是摆脱城市喧嚣的绝佳休闲方式，又能为艾因索菲重新伟大做出贡献。",
		id = 423211017
	},
	[423211018] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "像长水镇这种地方是最适合市民们周末度假的场所：交通便利，居民热情，风格独特。",
		id = 423211018
	},
	[423211019] = {
		speaker = "劳伦·莱特",
		prefab_name = "",
		content = "正是我的慧眼发掘了这处承载美好回忆的宝地，而这一切的故事，都要从我怀中的皮箱讲起……",
		id = 423211019
	},
	[423211020] = {
		speaker = "",
		prefab_name = "",
		content = "我远远地向劳伦·莱特点了下头，没有进一步打扰正亲自拍摄宣传片的市长。看着评估小镇情况的商业顾问们以及来探个新鲜的游客，我向伊兹尔笑了笑。",
		id = 423211020
	},
	[423211021] = {
		speaker = "我",
		prefab_name = "",
		content = "哦，还有……如果哪天成了旅游胜地，可要给我留个房间啊？",
		id = 423211021
	},
	[423211022] = {
		speaker = "伊兹尔",
		prefab_name = "",
		content = "嘿嘿，一定~你只要人过来就好。",
		id = 423211022
	},
	[423211023] = {
		speaker = "",
		prefab_name = "",
		content = "在又一次与大家逐一告别后，我和埃什总算是摆脱了热情的人群，站在车厢的入口处。朝阳正从地平线上缓缓升起，洒下金黄的希望。",
		id = 423211023
	},
	[423211024] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "走吧？该去我的新家看看了~",
		id = 423211024
	},
	[423211025] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "新的一段旅程，到底会是怎么样的呢？",
		id = 423211025
	},
	[423211026] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "呃……唔……嗯……",
		id = 423211026
	},
	[423211027] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "虽然想过很多种情况，但为什么入职之后要啃这么一本大部头啊！",
		id = 423211027
	},
	[423211028] = {
		speaker = "",
		prefab_name = "",
		content = "埃什捧着电子屏，不断地滑动浏览着与修正者相关的理论知识。在发现划过数个屏幕，进度条却几乎没动之后，她绝望地将求助的目光看向我。",
		id = 423211028
	},
	[423211029] = {
		speaker = "我",
		prefab_name = "",
		content = "毕竟你对相关知识还欠缺了解，理论扎实才方便出外勤啊。这几天辛苦一下吧。",
		id = 423211029
	},
	[423211030] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "这屏幕上的字比蚂蚁还要小，真想一口把它吃进去消化掉。为什么知识不能主动流进大脑呢？",
		id = 423211030
	},
	[423211031] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "每个修正者苏醒的时候都有这种机会啦，谁叫你当时可能……开小差了？",
		id = 423211031
	},
	[423211032] = {
		speaker = "埃克什瓦",
		prefab_name = "",
		content = "那又不能怪我嘛，总不能把我塞回盖亚重新苏醒一次。",
		id = 423211032
	},
	[423211033] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "#{nickname}#对你的评价可是很高的，相信你没问题。加油~",
		id = 423211033
	},
	[423211034] = {
		speaker = "",
		prefab_name = "",
		content = "留下隐隐有抓狂迹象的埃什继续与补习课件奋斗后，塞尔凯特拉着我换了个位置，笑眯眯地拍了拍我的肩膀。",
		id = 423211034
	},
	[423211035] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "作为第一次独自出外勤来说，你对状况的应对都很合适，表现无可挑剔。恭喜。",
		id = 423211035
	},
	[423211036] = {
		speaker = "我",
		prefab_name = "",
		content = "平时意外状况见得够多，遇上事也不足为奇了。怎么，有什么秘密想透露？",
		id = 423211036
	},
	[423211037] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "别想多嘛~只是一些例行的总结流程，有好几个人期待当面向你祝贺呢。",
		id = 423211037
	},
	[423211038] = {
		speaker = "我",
		prefab_name = "",
		content = "肯定有休，对吧？正好我也要感谢她在幕后的沟通。",
		id = 423211038
	},
	[423211039] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "她在办公室等你。修正者之间的矛盾牵扯面不小……原本不想让你被卷入的，但近来的情况还是迫使我们提前商议。",
		id = 423211039
	},
	[423211040] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "隐科组那边也有些事想问你，是关于你带回来的那把「枪」。",
		id = 423211040
	},
	[423211041] = {
		speaker = "我",
		prefab_name = "",
		content = "我听说红石河公会特地来要了一次，被休拒绝了？",
		id = 423211041
	},
	[423211042] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "奇械相当稀有，又能绕开盖亚对修正者的限制，他们当然会重视。",
		id = 423211042
	},
	[423211043] = {
		speaker = "我",
		prefab_name = "",
		content = "可如果我们要和他们有更多接触，就必须增进对它的了解。",
		id = 423211043
	},
	[423211044] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "没错。具体的你还是去找大国主她们吧，我可听不懂~",
		id = 423211044
	},
	[423211045] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "在忙完之后，记得把大家都喊上，带新人一块吃个饭，给你这趟旅程画一个圆满的句号。",
		id = 423211045
	},
	[423211046] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "总之，埃什，还有#{nickname}#……",
		id = 423211046
	},
	[423211047] = {
		speaker = "塞尔凯特",
		prefab_name = "",
		content = "欢迎回家。",
		id = 423211047
	},
	[1106101001] = {
		speaker = "我",
		prefab_name = "",
		content = "执明？呃……有人吗？",
		id = 1106101001
	},
	[1106101002] = {
		speaker = "",
		prefab_name = "",
		content = "偌大的办公室里看不到人影，安静得落针可闻。我只好一路往前走，直到来到办公桌前，才隐约看到杂物堆后的身影。",
		id = 1106101002
	},
	[1106101003] = {
		speaker = "",
		prefab_name = "",
		content = "执明就趴在桌案上睡着，呼吸微弱到让人觉得是不是出了什么问题。",
		id = 1106101003
	},
	[1106101004] = {
		speaker = "我",
		prefab_name = "",
		content = "咳咳……那个，执明？我回来了。",
		id = 1106101004
	},
	[1106101005] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "？！……",
		id = 1106101005
	},
	[1106101006] = {
		speaker = "我",
		prefab_name = "",
		content = "哎哎哎，玄机收起来！是我。",
		id = 1106101006
	},
	[1106101007] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "……我刚刚睡着了。",
		id = 1106101007
	},
	[1106101008] = {
		speaker = "",
		prefab_name = "",
		content = "她似乎被我惊吓到了，短暂平静一下后，开始慌慌张张打理起自己有些凌乱的头发。",
		id = 1106101008
	},
	[1106101009] = {
		speaker = "我",
		prefab_name = "",
		content = "你不会一直没离开这里吧？是不是该找张床好好休息一下？",
		id = 1106101009
	},
	[1106101010] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "不用。",
		id = 1106101010
	},
	[1106101011] = {
		speaker = "",
		prefab_name = "",
		content = "她的目光扫过面前的屏幕，随后抬起头盯着我。",
		id = 1106101011
	},
	[1106101012] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "已经十一点多了。所以你去赤炁堂看个病，看了整整一下午，加一晚上？",
		id = 1106101012
	},
	[1106101013] = {
		speaker = "我",
		prefab_name = "",
		content = "从结果上来说……是的。",
		id = 1106101013
	},
	[1106101014] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "有那么多事需要做吗？",
		id = 1106101014
	},
	[1106101015] = {
		speaker = "",
		prefab_name = "",
		content = "在她怀疑的目光下，我只好把背在身后的手拿出来。手上的东西自然而然吸引了她的注意。",
		id = 1106101015
	},
	[1106101016] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "这是什么？",
		id = 1106101016
	},
	[1106101017] = {
		speaker = "我",
		prefab_name = "",
		content = "赤炁堂特制的膏药，安神用的，说是能减少焦虑。还有你的健康报告，两个月前的，听说给你发了好几次通知，你都没去领。",
		id = 1106101017
	},
	[1106101018] = {
		speaker = "我",
		prefab_name = "",
		content = "这两个都是给你的。我自己的事不到一个小时就解决了。",
		id = 1106101018
	},
	[1106101019] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "……你早点直接回来不就好了？这些东西没什么用的。",
		id = 1106101019
	},
	[1106101020] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我的情况我自己知道。健康报告这种东西，每次都是一样的结果，很久以前就没再看过了。",
		id = 1106101020
	},
	[1106101021] = {
		speaker = "我",
		prefab_name = "",
		content = "陵光也猜到你会这么说了。",
		id = 1106101021
	},
	[1106101022] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "我也猜到陵光猜到我会这么说了。",
		id = 1106101022
	},
	[1106101023] = {
		speaker = "",
		prefab_name = "",
		content = "啊？/套娃呢？",
		id = 1106101023
	},
	[1106101024] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "总之不用担心。话说回来，我的实验数据怎么样了？",
		id = 1106101024
	},
	[1106101025] = {
		speaker = "我",
		prefab_name = "",
		content = "弥弥尔刚刚返给我，结果正常。不出意外的话，可以继续往下推进了。",
		id = 1106101025
	},
	[1106101026] = {
		speaker = "执明",
		prefab_name = "1061ui_story",
		content = "那就继续……",
		id = 1106101026
	},
	[1106101027] = {
		speaker = "我",
		prefab_name = "",
		content = "但是现在有意外。",
		id = 1106101027
