	},
	[322021133] = {
		speaker = "洛肯",
		prefab_name = "404001ui_story",
		content = "耳朵不会只听到自己感兴趣的话题。加尔有不少年纪大的人经常说起，「要是那个马拉塔来的年轻人选上了会怎么怎么样」。",
		id = 322021133
	},
	[322021134] = {
		speaker = "萨穆雅",
		prefab_name = "",
		content = "……没那么简单，基维塔巴的本土势力盘根错节，当时竞选已经遇到了很大的阻碍。",
		id = 322021134
