		id = 322051004
	},
	[322051005] = {
		speaker = "红狐",
		prefab_name = "10049ui_story",
		content = "上个纪元留下来的修复程序，现在差不多失效了，不然阿波菲斯也出不来。",
		id = 322051005
	},
	[322051006] = {
