	[322051007] = {
		speaker = "红狐",
		prefab_name = "10049ui_story",
		content = "呵呵，你跟我还解释什么。「特许近卫军与内部秘密行动处」，看名字就明白，你们不干这种出门打猎的活儿。",
		id = 322051007
	},
	[322051008] = {
		speaker = "红狐",
		prefab_name = "10049ui_story",
		content = "我猜外面那帮小崽子现在又在犯嘀咕：「出那么大的事，奥贝里克上哪儿去了？」",
