	},
	[322112096] = {
		speaker = "",
		prefab_name = "",
		content = "书记官吞吞吐吐的态度让涅赫贝特感到有些恼火，但想到他过往几乎没有过这样失态的表现，加上他语气似乎有些激动，涅赫贝特还是朝窗外望了一眼。",
		id = 322112096
	},
	[322112097] = {
		speaker = "",
		prefab_name = "",
		content = "大概是习惯了头顶只有昏沉的赤红，重新在天空中看到青蓝色时，涅赫贝特不禁微微眯起眼睛。",
		id = 322112097
	},
	[322112098] = {
		speaker = "",
		prefab_name = "",
		content = "那交融的颜色起初只有一线，在天际边缘缓慢拉长，仿佛日出时地平线的蜃景。然后——",
		id = 322112098
	},
	[322112099] = {
		speaker = "",
		prefab_name = "",
		content = "恢弘而洁净的青蓝色光华从那一线缝隙中如瀑布般倾泻而下，又沿着颠倒的抛物线回升到起始的高度，一浪一浪，像是倒悬于高天的海啸，朝基维塔巴上空漫卷而来。",
		id = 322112099
	},
	[322112100] = {
