	[322161082] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "哼，就这还想跟我斗嘴，真好搞定。",
		id = 322161082
	},
	[322161083] = {
		speaker = "我",
		prefab_name = "",
		content = "（到底谁更好搞定啊……）",
		id = 322161083
	},
	[322161084] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "伊里伽尔呢？怎么没来迎接我？",
		id = 322161084
	},
	[322161085] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "阿卡德帮重组了，她在处理自家的事。再说没人知道你会出现在这里，我们执行公务，她没有权限参与。",
		id = 322161085
	},
	[322161086] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "哈？都是一起揍过阿波菲斯的交情了，还分什么权限不权限？",
		id = 322161086
	},
	[322161087] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "一码归一码，你也是。我需要确认你现在的所属组织，谁对你的行为负责。",
		id = 322161087
	},
	[322161088] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "一定要有个组织吗？那要不就深空之眼？",
		id = 322161088
	},
	[322161089] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "真的可以吗？",
		id = 322161089
	},
	[322161090] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "啊？为什么不……哦，咳！那个……",
		id = 322161090
	},
	[322161091] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "怎么了？有什么不方便的地方吗？",
		id = 322161091
	},
	[322161092] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "因为冥王跟我说——",
		id = 322161092
	},
	[322161093] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "停！停！用不着你复述一遍。",
		id = 322161093
	},
	[322161094] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "……再说不把你打发走，你岂不是又要赖在源层拖我后腿了？",
		id = 322161094
	},
	[322161095] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "你是……故意那么说的吗？",
		id = 322161095
	},
	[322161096] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "啊……反正差不多就这个意思吧，你也真是笨，伊里伽尔都听出来我在骗你了。",
		id = 322161096
	},
	[322161097] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "当然也不全是骗你，「不想有人来招惹我」什么的……你要生气就生气好了。",
		id = 322161097
	},
	[322161098] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "冥王……",
		id = 322161098
	},
	[322161099] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "对不起……我就知道……你不会……",
		id = 322161099
	},
	[322161100] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "哎行了行了，我就是不喜欢深空之眼这种地方，太多像你这样的小鬼，受委屈了就哭鼻子，跟过家家一样。",
		id = 322161100
	},
	[322161101] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "我没有委屈……呜……我是高兴……",
		id = 322161101
	},
	[322161102] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "……哼，你要是学会生气，我都当你长大了。",
		id = 322161102
	},
	[322161103] = {
		speaker = "奥西里斯",
		prefab_name = "1011ui_story",
		content = "那……那你会跟我们一起回去吗？",
		id = 322161103
	},
	[322161104] = {
		speaker = "荷鲁斯",
		prefab_name = "",
		content = "我？我都行吧。除了房间小点，倒也没什么不好的……你说呢，人类？",
		id = 322161104
	},
	[322161105] = {
		speaker = "",
		prefab_name = "",
		content = "我在录音里说过",
		id = 322161105
	},
	[322161106] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "听到了吧，深空之眼。至于谁对我的行为负责嘛，那当然是我自己。",
		id = 322161106
	},
	[322161107] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "如果你的所属组织是深空之眼，那对你的行为负责的人就是奥丁，你也要接受她的管辖，明白吗？",
		id = 322161107
	},
	[322161108] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "啊？这么麻烦，那要不换一个……",
		id = 322161108
	},
	[322161109] = {
		speaker = "",
		prefab_name = "",
		content = "从我身上跳下来，荷鲁斯摸了摸下巴，忽然注意到奥西里斯盯着自己，啧啧嘴，没有说下去。",
		id = 322161109
	},
	[322161110] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "哎，也行吧，奥丁的实力我还是认的，听她唠叨两句也没什么。",
		id = 322161110
	},
	[322161111] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "冥王，你是不是变强了？",
		id = 322161111
	},
	[322161112] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "我都没动手，你能看出来？",
		id = 322161112
	},
	[322161113] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "算是感觉吧……有些在另一个层次的东西。",
		id = 322161113
	},
	[322161114] = {
		speaker = "涅赫贝特",
		prefab_name = "10104ui_story",
		content = "就是因为你现在的实力，我才需要问清楚。否则你出了问题，恐怕整个盖亚都找不到几个能压住你的人。",
		id = 322161114
	},
	[322161115] = {
		speaker = "我",
		prefab_name = "",
		content = "这么强了？！",
		id = 322161115
	},
	[322161116] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "……还好吧，跟原来比也没强多少。",
		id = 322161116
	},
	[322161117] = {
		speaker = "",
		prefab_name = "",
		content = "不知道为什么，谈到这个话题，冥王一贯张狂的气势莫名其妙地弱了下去。",
		id = 322161117
	},
	[322161118] = {
		speaker = "",
		prefab_name = "",
		content = "比起「她忽然变得谦虚了」，我更愿意相信这里面还有别的原因。想到她主动提到了伊里伽尔，我忽然想起一件似乎所有人都没太在意的事。",
		id = 322161118
	},
	[322161119] = {
		speaker = "我",
		prefab_name = "",
		content = "冥王。",
		id = 322161119
	},
	[322161120] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "干嘛？都说了叫我荷鲁斯了。",
		id = 322161120
	},
	[322161121] = {
		speaker = "我",
		prefab_name = "",
		content = "抱歉，顺口……只是问一下……你和伊里伽尔说的那位「梅塞可」呢？",
		id = 322161121
	},
	[322161122] = {
		speaker = "",
		prefab_name = "",
		content = "在场的大多数人只听说过这个名字，听到我的疑问，都有些好奇地看向荷鲁斯。",
		id = 322161122
	},
	[322161123] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "啊，她、她啊……",
		id = 322161123
	},
	[322161124] = {
		speaker = "我",
		prefab_name = "",
		content = "（还是和以前一样，不会藏心事啊……）",
		id = 322161124
	},
	[322161125] = {
		speaker = "",
		prefab_name = "",
		content = "如果不方便说的话……",
		id = 322161125
	},
	[322161126] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "没什么不方便的。",
		id = 322161126
	},
	[322161127] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "离开……算是吧。",
		id = 322161127
	},
	[322161128] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "哎不管了……首先，她不叫什么「梅塞可」，她就是拉。",
		id = 322161128
	},
	[322161129] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "对，就是你们想的那个拉，原初修正者。做点惊讶的表情就够了，别打断我。",
		id = 322161129
	},
	[322161130] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "其次，她……",
		id = 322161130
	},
	[322161131] = {
		speaker = "",
		prefab_name = "",
		content = "大概是还没想好说辞，荷鲁斯又犹豫了好一会儿，忽然像是随手找个东西发泄一下压力似地，重重拍了一把我的后背。",
		id = 322161131
	},
	[322161132] = {
		speaker = "",
		prefab_name = "",
		content = "借着我痛呼的掩护，她闷闷地叹了口气，很快恢复了平常意兴索然的模样。",
		id = 322161132
	},
	[322161133] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "她救了我。",
		id = 322161133
	},
	[322161134] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "说实话，没必要。论实力，她比我更有资格活着。但她总有一堆乱七八糟的道理，又说她不一定有机会……天知道真的假的。",
		id = 322161134
	},
	[322161135] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "所以，如果你们觉得我代替不了她，或者是我害了她，那就这么想吧。",
		id = 322161135
	},
	[322161136] = {
		speaker = "奥西里斯",
		prefab_name = "1211ui_story",
		content = "这不是你的错呀，冥王，我们不会这样想的。",
		id = 322161136
	},
	[322161137] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "啧……我没在说反话，你们就该这样想，都给我这样记住她。",
		id = 322161137
	},
	[322161138] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "她是个滥好人，好心到没救的那种……如果只是这样，我会觉得很好笑。",
		id = 322161138
	},
	[322161139] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "但拉不一样，她真的这样去做了。",
		id = 322161139
	},
	[322161140] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "明明什么都有了，却宁愿什么都不要，什么都可以舍弃，就算不会被人记住……她也想救下更多的人，想拯救这个糟糕透顶的世界。",
		id = 322161140
	},
	[322161141] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "如果这样的家伙都不配活下来，我们又算什么……",
		id = 322161141
	},
	[322161142] = {
		speaker = "我",
		prefab_name = "",
		content = "当然算你自己。",
		id = 322161142
	},
	[322161143] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "……",
		id = 322161143
	},
	[322161144] = {
		speaker = "我",
		prefab_name = "",
		content = "梵天和我说过，拉选择救你，不是为了让你代替她。",
		id = 322161144
	},
	[322161145] = {
		speaker = "我",
		prefab_name = "",
		content = "你就是你，是她救过的无数人里的一个。不用因为这件事给自己太大压力。",
		id = 322161145
	},
	[322161146] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "呵，你也这么说。",
		id = 322161146
	},
	[322161147] = {
		speaker = "我",
		prefab_name = "",
		content = "还有谁……拉吗？",
		id = 322161147
	},
	[322161148] = {
		speaker = "",
		prefab_name = "",
		content = "荷鲁斯沉默了一会儿，抬手打了个响指。一枚淡金色的光铸符文浮现出来，形状是上端呈圆柄状的十字，似虚似实，悬停在她面前。",
		id = 322161148
	},
	[322161149] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "她习惯了这东西的重量，我还没有。可等我习惯了，还能说不是在代替她吗？",
		id = 322161149
	},
	[322161150] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "……真是的，这家伙，偏偏留到最后一次见面才把这么麻烦的东西塞给我。",
		id = 322161150
	},
	[322161151] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "这样不就……连还回去的机会都没有了吗？",
		id = 322161151
	},
	[322161152] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "你……",
		id = 322161152
	},
	[322161153] = {
		speaker = "",
		prefab_name = "",
		content = "澄澈的水面从脚下向望不到边的天际延伸，雕塑般的巨构耸立在因缺少参照而失去距离感的远方。",
		id = 322161153
	},
	[322161154] = {
		speaker = "",
		prefab_name = "",
		content = "每一寸空间均匀地填充着宁静，一点点溶化了战场残留在耳畔的回响。",
		id = 322161154
	},
	[322161155] = {
		speaker = "",
		prefab_name = "",
		content = "基维塔巴、阿波菲斯、纷飞的炮火与光束、镰刀劈砍核心的脆响……仿佛那一切都是随着长梦远去的幻景，可醒来后的「现实」却更加失真。",
		id = 322161155
	},
	[322161156] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "你，还活着吗？",
		id = 322161156
	},
	[322161157] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "我只是一点残留的意识。没有小冥王，我要怎么存在呢？",
		id = 322161157
	},
	[322161158] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "这里是我的「心象」。我只是把我们的意识，停在了弥留的一瞬而已。",
		id = 322161158
	},
	[322161159] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "为什么？你答应过，不会两条命都搭进来。",
		id = 322161159
	},
	[322161160] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "我的灵魂毕竟已经不完整了，只是一点意识，就算有生死权能，想活过来也太勉强。",
		id = 322161160
	},
	[322161161] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "但是我没有说谎……抱歉，玩了一点文字游戏。",
		id = 322161161
	},
	[322161162] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "能不能别再拿你那些歪理糊弄我……",
		id = 322161162
	},
	[322161163] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "小冥王，成为真正的修正者吧。",
		id = 322161163
	},
	[322161164] = {
		speaker = "",
		prefab_name = "",
		content = "一时间没听明白梅塞可的意思，冥王张着嘴，怔怔地看着对方，很想埋怨她这种时候不该开玩笑。",
		id = 322161164
	},
	[322161165] = {
		speaker = "",
		prefab_name = "",
		content = "但认真与玩笑的表情，冥王能分得清。",
		id = 322161165
	},
	[322161166] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "对盖亚来说，你就是我的一部分。比起让我复活，把我作为修正者的资格给你，要简单得多。",
		id = 322161166
	},
	[322161167] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "……你知不知道自己在说什么？这可是活下去的机会。",
		id = 322161167
	},
	[322161168] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "对你来说也一样呀，你也想要活下去吧。",
		id = 322161168
	},
	[322161169] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "这跟我怎么想没关系！你是原初修正者，傻子都知道你活着比我更有用啊。",
		id = 322161169
	},
	[322161170] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "可那个傻子不一定认识我。",
		id = 322161170
	},
	[322161171] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "喂，扯歪理就没意思了，又不是真的有个傻子。",
		id = 322161171
	},
	[322161172] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "但是，会在意你的人，一定比会在意我的人多。",
		id = 322161172
	},
	[322161173] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "我没有在这个纪元生活过。我熟悉的一切，还有熟悉我的一切，大多已经不在了。",
		id = 322161173
	},
	[322161174] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "奥丁还有梵天她们也都接受了我的死。她们都是很优秀的人，有自己的目标，即便我不在也没关系。",
		id = 322161174
	},
	[322161175] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "哪有这回事……",
		id = 322161175
	},
	[322161176] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "但是你不一样，小冥王。尽管你醒过来的时间不长，这个世界上已经有许多爱你和关心你的人。",
		id = 322161176
	},
	[322161177] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "他们会为你哭，为你笑，会想念你，崇拜你。他们不会忘记你，你与他们之间的牵绊已经成为了他们生命的一部分，这就是你更应该活下去的理由。",
		id = 322161177
	},
	[322161178] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "因为生命的重量并不依靠本身的强弱，而在于彼此的连结。互相依靠，互相成就，互相关怀，也互相珍重。",
		id = 322161178
	},
	[322161179] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "我不算吗……",
		id = 322161179
	},
	[322161180] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "嗯？",
		id = 322161180
	},
	[322161181] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "我不算在意你的人吗？我不想你死！你怎么不考虑这个？",
		id = 322161181
	},
	[322161182] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "随随便便救了我，丢给我一堆东西，然后就这样走掉了，难道你以为我会原谅你吗？！",
		id = 322161182
	},
	[322161183] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "是嘛……我很高兴，能听到小冥王坦率地这么说。",
		id = 322161183
	},
	[322161184] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "那就给我——",
		id = 322161184
	},
	[322161185] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "就当是我最后的请求，好吗？",
		id = 322161185
	},
	[322161186] = {
		speaker = "",
		prefab_name = "",
		content = "冥王紧捏着拳头，最终还是没有说下去，咬着嘴唇把头扭到一边。",
		id = 322161186
	},
	[322161187] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "抱歉，是小冥王先说了耍赖的话，我也只好……",
		id = 322161187
	},
	[322161188] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "到底谁在耍赖啊，非要到这种时候才说……",
		id = 322161188
	},
	[322161189] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "因为……我也会舍不得。我怕太早开口，自己会动摇。",
		id = 322161189
	},
	[322161190] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "但那样是不应该的。我的生命已经够精彩了。那么多个纪元，发生过那么多的事，凯米特、晨昏塔……真是怎么想都想不完。",
		id = 322161190
	},
	[322161191] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "我们能在这里说话，是命运给了我最后一次奇迹。有小冥王陪我走完最后一程，要是再说遗憾，就太贪心了。",
		id = 322161191
	},
	[322161192] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "不要有难过的表情，好吗？告别的时候，还是笑一笑更合适。",
		id = 322161192
	},
	[322161193] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "我才不像你，什么时候都笑得出来。",
		id = 322161193
	},
	[322161194] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "但是，生命开始了一段旅程，的确是值得高兴的事。",
		id = 322161194
	},
	[322161195] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "以后你会走过各种各样的地方，遇到各种各样的人……但是不管什么时候，都不可以欺负别人，要和大家好好相处。",
		id = 322161195
	},
	[322161196] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "你会发现许多感兴趣的事，会有开心和烦恼，也会有梦想与责任。每段经历都是你与世界在互相改变，学会珍惜它们。",
		id = 322161196
	},
	[322161197] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "然后，就按照你想成为的样子，生活下去吧，成为可以让大家瞻仰的、了不起的修正者。",
		id = 322161197
	},
	[322161198] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "……啊，不用你说我也会这么做。",
		id = 322161198
	},
	[322161199] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "嗯~我知道小冥王是很可靠的孩子。",
		id = 322161199
	},
	[322161200] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "哎呀，时间真的不多了，我想一想，还有什么没说——",
		id = 322161200
	},
	[322161201] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "鸡毛蒜皮的事差不多够了吧，为什么一直在说我的事？你自己呢？",
		id = 322161201
	},
	[322161202] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "啊！我想到了！",
		id = 322161202
	},
	[322161203] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "喂，你有没有在听……",
		id = 322161203
	},
	[322161204] = {
		speaker = "梅塞可",
		prefab_name = "",
		content = "那个……我苏醒比你早，所以，叫我一声「姐姐」可以吗？",
		id = 322161204
	},
	[322161205] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "这种时候还占我便宜？谁要叫你——",
		id = 322161205
	},
	[322161206] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "……",
		id = 322161206
	},
	[322161207] = {
		speaker = "",
		prefab_name = "",
		content = "脚下平静的水面忽然点开一圈涟漪，荡漾着笼盖冥王的晴空。",
		id = 322161207
	},
	[322161208] = {
		speaker = "",
		prefab_name = "",
		content = "她抬头望着这片光，温暖又柔和的光，毫无保留地与自己拥抱。",
		id = 322161208
	},
	[322161209] = {
		speaker = "",
		prefab_name = "",
		content = "仿佛离去的人，只将这光留给了她，怕她在黑暗与寒冷中困顿，也怕她看清互相不舍的背影。",
		id = 322161209
	},
	[322161210] = {
		speaker = "冥王",
		prefab_name = "1044ui_story",
		content = "……姐姐。",
		id = 322161210
	},
	[322161211] = {
		speaker = "",
		prefab_name = "",
		content = "再短的刹那也只能向前。声音追不上背影，鹏鸟也追不上白驹。",
		id = 322161211
	},
	[322171001] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "小冥王……",
		id = 322171001
	},
	[322171002] = {
		speaker = "",
		prefab_name = "",
		content = "听到身后梅塞可的声音，冥王微微偏过头，不过很快又转回正前方，闷闷不乐地甩出手里的晶石碎块。",
		id = 322171002
	},
	[322171003] = {
		speaker = "",
		prefab_name = "",
		content = "碎块飞得很远，在空中画出一道平滑的抛物线，越过一块在战斗中被打得支离破碎的平台，终于开始加速下坠，沉入平台边缘外的深渊。",
		id = 322171003
	},
	[322171004] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我要是有说话的兴致，就不会跑来这种地方了。",
		id = 322171004
	},
	[322171005] = {
		speaker = "",
		prefab_name = "",
		content = "冥王所坐的位置离地约有二十米高，那是一截斜向上弯曲表面如同枯枝的无机质结构，下方的地面空荡荡的，从冥王的高度才能看到在两公里外安营的人群。",
		id = 322171005
	},
	[322171006] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "需要安慰的是他们……一帮喜欢逞能的笨蛋，等我死了，他们也该喂视骸了。",
		id = 322171006
	},
	[322171007] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "倒也不会这么快，我还在呢。",
		id = 322171007
	},
	[322171008] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "早一点晚一点有什么区别？等你说的那个「阿菲波斯」来了——",
		id = 322171008
	},
	[322171009] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "是「阿波菲斯」啦。",
		id = 322171009
	},
	[322171010] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "阿波……我管它叫阿什么？！不如叫它「啊，死定了」，反正最后肯定所有人都在想这个。",
		id = 322171010
	},
	[322171011] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "你会害怕死亡吗？",
		id = 322171011
	},
	[322171012] = {
		speaker = "",
		prefab_name = "",
		content = "刚从手边摸起一块石头，听到梅塞可的话，冥王的手慢慢垂下，回头直勾勾地盯着梅塞可看了一会儿，把石头不轻不重地扔到她脚边。",
		id = 322171012
	},
	[322171013] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我发现了，你和休就是一类人，动不动就开始问一些莫名其妙的问题，又不说为什么要问，感觉这样就可以站得比别人高一头。",
		id = 322171013
	},
	[322171014] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "休吗……",
		id = 322171014
	},
	[322171015] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哦，你都不认识那家伙，跟你说了也是白说。",
		id = 322171015
	},
	[322171016] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "但是我都已经问了，不可以回答一下吗？",
		id = 322171016
	},
	[322171017] = {
		speaker = "",
		prefab_name = "",
		content = "冥王啧啧嘴，没再看梅塞可，目光穿过枯枝、地面与晶壁间的缝隙，无精打采地落在极远处的虚空中。",
		id = 322171017
	},
	[322171018] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我怎么可能有那种胆小鬼才会有的想法……要是怕死，我就不会救奥西里斯了。",
		id = 322171018
	},
	[322171019] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "让人不爽的，是只能在这里干等啊。",
		id = 322171019
	},
	[322171020] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "没法报仇，找不到帮手，只有个百分之一千打不过的大家伙，甚至都不知道是它先来还是我先死……",
		id = 322171020
	},
	[322171021] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "这样干等着，不就和那些没用的人类一样了吗？",
		id = 322171021
	},
	[322171022] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "谁都会遇到力不从心的时候。我们能做到的，也只比普通人多了一点点而已。",
		id = 322171022
	},
	[322171023] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你的「一点点」可真够夸张的……",
		id = 322171023
	},
	[322171024] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "再说就算只多一点点，也别把我和那些没用的家伙混为一谈啊。",
		id = 322171024
	},
	[322171025] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "呵呵，很要强呢。",
		id = 322171025
	},
	[322171026] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "有什么好笑的？该你说了。",
		id = 322171026
	},
	[322171027] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "嗯？想要我说什么？",
		id = 322171027
	},
	[322171028] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "怕不怕死啊。虽然不知道你还有什么本事，但我打不过阿波菲斯，你怕是也活不了。",
		id = 322171028
	},
	[322171029] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……不过看你这副悠闲的样子，不用问也知道了。",
		id = 322171029
	},
	[322171030] = {
		speaker = "",
		prefab_name = "",
		content = "梅塞可走到冥王旁边，整理好裙子，慢悠悠地坐下来，像是两个并排坐在海边的沙滩上等待日出的旅人。",
		id = 322171030
	},
	[322171031] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "我当然是……害怕死亡的。",
		id = 322171031
	},
	[322171032] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哼，你不会是故意和我反着说吧？",
		id = 322171032
	},
	[322171033] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "没有这回事。不过我们对这句话的理解可能有一点点不一样。",
		id = 322171033
	},
	[322171034] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "对我来说，「死亡」只是「生命的失去」。",
		id = 322171034
	},
	[322171035] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……这不是废话？",
		id = 322171035
	},
	[322171036] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "但有什么是我们不会失去的呢？即便我们倾注再多情感，再怎么不舍，最终也都会分别。",
		id = 322171036
	},
	[322171037] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "财富与权力，朋友与家人，孩子手中的玩具，旅人寻找的风景，甚至是让这一切有意义的生命……",
		id = 322171037
	},
	[322171038] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "这样的现实很残酷，光是想象「失去」那一刻——我们珍爱的、习以为常的，从那以后就再也不见了，这就足够让人难过了。",
		id = 322171038
	},
	[322171039] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "这是一回事吗？别的东西没了还可以再有，命没了就是没了。",
		id = 322171039
	},
	[322171040] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "是啊，命没了就是没了……这是世界的规则。",
		id = 322171040
	},
	[322171041] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "所以我才说，我们的理解可能并不一样……",
		id = 322171041
	},
	[322171042] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "有的时候，生者未必是生，死者未必是死，规则未必不能改变。",
		id = 322171042
	},
	[322171043] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "就像你现在还在这里，能和我说话，能保护人类，能在没人的地方生闷气，谁能否认你还活着呢？",
		id = 322171043
	},
	[322171044] = {
		speaker = "",
		prefab_name = "",
		content = "梅塞可摊开手掌，一枚淡金色的光铸符文浮现出来。冥王感觉这枚符文有些熟悉，莫名想要伸手去拿，但又不好意思向梅塞可开口，只好把头扭开不去看它。",
		id = 322171044
	},
	[322171045] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "这什么？",
		id = 322171045
	},
	[322171046] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "帮你维持住身体的东西。",
		id = 322171046
	},
	[322171047] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你……这种东西还拿出来乱玩？！搞坏了怎么办？",
		id = 322171047
	},
	[322171048] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "呵呵，不用担心，它比权钥还要牢固哦~",
		id = 322171048
	},
	[322171049] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "但就像我说的，总有一天，连它也会消失。到那时，我就没办法像这样挽救别人、帮助别人了。",
		id = 322171049
	},
	[322171050] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "我们害怕死亡，害怕「万事万物的失去」，是因为我们习惯了拥有，习惯用「拥有」来支撑生命，再用生命本身来支撑我们期盼的一切。",
		id = 322171050
	},
	[322171051] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "弄丢玩具的孩子会哭闹，因为以后再也感受不到同样的快乐。错过风景的旅人会惋惜，因为相同的旅程，一生或许只有一次。",
		id = 322171051
	},
	[322171052] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "小冥王，我们害怕失去生命，究竟是在害怕什么呢？你想要用生命去支撑的期盼，又是什么呢？",
		id = 322171052
	},
	[322171053] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……",
		id = 322171053
	},
	[322171054] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哪有那么复杂……不想死就不想死，非要找那么多借口。我又不会笑话你。",
		id = 322171054
	},
	[322171055] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "待在源层真是无聊得要命。你讲了这么一大通，我居然全听完了。",
		id = 322171055
	},
	[322171056] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "你很想回表层吗？",
		id = 322171056
	},
	[322171057] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我不怕死，不代表我不想活了，好吗？",
		id = 322171057
	},
	[322171058] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "要是表层没我的事，我留在这里也无所谓。我又不像那些爱做梦的小鬼，有一大堆愿望啊、梦想啊非完成不可。",
		id = 322171058
	},
	[322171059] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "可谁知道那帮没用的家伙是不是在哭哭啼啼等我去救他们……",
		id = 322171059
	},
	[322171060] = {
		speaker = "",
		prefab_name = "",
		content = "冥王拍拍屁股站起来，抬眼朝远方张望了一圈，忽然挑起眉头。",
		id = 322171060
	},
	[322171061] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你说这源层里，除了我们，还有其他会动的东西吗？",
		id = 322171061
	},
	[322171062] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "视骸？",
		id = 322171062
	},
	[322171063] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "呵，听到我抱怨无聊，送上门来给我解闷吗？",
		id = 322171063
	},
	[322171064] = {
		speaker = "",
		prefab_name = "",
		content = "微微眯起双眼，还是没能看清远处那一线红色的东西到底是什么。但眼下似乎没有别的解释，冥王扛起生魂，从这截「枯枝」上一跃而下。",
		id = 322171064
	},
	[322171065] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "眼前有事能做，也懒得想那么多了！",
		id = 322171065
	},
	[322181001] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "为什么会有这种小型视骸……",
		id = 322181001
	},
	[322181002] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "啊？你嘀咕什么呢？",
		id = 322181002
	},
	[322181003] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "这些视骸，也许是阿波菲斯的一部分，或者是它召唤出来的。",
		id = 322181003
	},
	[322181004] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "为什么？长得很像阿波菲斯吗？",
		id = 322181004
	},
	[322181005] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "骸能的特性，还有这种原子反应……",
		id = 322181005
	},
	[322181006] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "什么反应？",
		id = 322181006
	},
	[322181007] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "唔，你知道太阳为什么会发光吗？",
		id = 322181007
	},
	[322181008] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "不知道。",
		id = 322181008
	},
	[322181009] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "那就不好解释了……不过没关系，看上去对你来说和普通的爆炸差不多。",
		id = 322181009
	},
	[322181010] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "怎么听着有点不爽……算了，懒得和你计较。",
		id = 322181010
	},
	[322181011] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你的意思是，阿波菲斯已经复活了？",
		id = 322181011
	},
	[322181012] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "阿波菲斯形成的过程，我知道的也有限。未必已经复活，但至少要做好准备才行。",
		id = 322181012
	},
	[322181013] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "都到这时候了，还能准备什么？你给我的「魂魄」也用光了，该怎么样就怎么样吧。",
		id = 322181013
	},
	[322181014] = {
		speaker = "",
		prefab_name = "",
		content = "冥王翻了个白眼，绕过梅塞可，朝她身后的方向走去。\n这处平台离幸存者们的临时营地不远。一些人等到战斗的声响结束就靠了过来。",
		id = 322181014
	},
	[322181015] = {
		speaker = "",
		prefab_name = "",
		content = "冥王抬手正想示意他们不要走近。可望着几百米外的人群，她忽然又停了下来。",
		id = 322181015
	},
	[322181016] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "喂，反正也没什么可准备的，不如现在就去找阿波菲斯好了。",
		id = 322181016
	},
	[322181017] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "嗯？为什么忽然这么想？",
		id = 322181017
	},
	[322181018] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我按着那条怪蛇打的时候，伊里伽尔能打开通道回去。等我把它杀了，反倒又不行了。",
		id = 322181018
	},
	[322181019] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "这不就说明，它妨碍我们开门的能力，现在还在别的什么地方。要么被人偷走了，要么本来就是别人借给它的。",
		id = 322181019
	},
	[322181020] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "最可疑的，不就是阿波菲斯？",
		id = 322181020
	},
	[322181021] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "呵呵，是在想该怎么救他们吗？小冥王越来越善良了~",
		id = 322181021
	},
	[322181022] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……少啰嗦。跟你说了，答应你的事，我说到做到。",
		id = 322181022
	},
	[322181023] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "可是，你要怎么找到阿波菲斯呢？",
		id = 322181023
	},
	[322181024] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "就像这些人类到哪儿都要跟着我，如果刚才那些爬虫都是阿波菲斯搞出来的，那顺着它们出现的方向找过去不就行了？",
		id = 322181024
	},
	[322181025] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "至于能不能打得过，总要试试，就算它再强，我还真不信能让我还不了手。",
		id = 322181025
	},
	[322181026] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "说不定还能逮到那家伙刚苏醒最虚弱的时候，直接把它宰了。",
		id = 322181026
	},
	[322181027] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "这……不排除这种可能。但如果你离开了，他们呢？",
		id = 322181027
	},
	[322181028] = {
		speaker = "阿齐姆",
		prefab_name = "",
		content = "远、远征？",
		id = 322181028
	},
	[322181029] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "没错，远征！",
		id = 322181029
	},
	[322181030] = {
		speaker = "",
		prefab_name = "",
		content = "威风凛凛地站在一座用石块垒砌的演讲台上，冥王俯视台下茫然无措的人类，掏出生魂重重敲了两下地面。",
		id = 322181030
	},
	[322181031] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "视骸一直冒出来，就是因为它们有个首领。",
		id = 322181031
	},
	[322181032] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你们要是还想回家，就祈祷我能找到那个首领，然后把它干掉吧！",
		id = 322181032
	},
	[322181033] = {
		speaker = "高尔",
		prefab_name = "",
		content = "我们当然不会质疑冥王大人的实力。可……您要离开多久？",
		id = 322181033
	},
	[322181034] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "怎么？伊里伽尔帮你们开门的时候一个个充好汉，这时候又怕死了？",
		id = 322181034
	},
	[322181035] = {
		speaker = "高尔",
		prefab_name = "",
		content = "这……",
		id = 322181035
	},
	[322181036] = {
		speaker = "",
		prefab_name = "",
		content = "人们面面相觑。即便圆滑如高尔，事到临头也不知道该怎么在这种问题上打圆场。左右看看众人都是一样为难的表情，他也只能叹了口气。",
		id = 322181036
	},
	[322181037] = {
		speaker = "高尔",
		prefab_name = "",
		content = "冥王大人，那时候大家留下，是因为知道如果不留下，您和伊里伽尔大人就要坚持不住了。",
		id = 322181037
	},
	[322181038] = {
		speaker = "高尔",
		prefab_name = "",
		content = "可您不在，我们就只能干等着，不知道您什么时候回来，也不知道逃命有什么意义。",
		id = 322181038
	},
	[322181039] = {
		speaker = "阿齐姆",
		prefab_name = "",
		content = "大家都在基维塔巴混，真不怕死的，大多早就死了；也不至于不敢拼命……但至少该知道往哪里使劲。",
		id = 322181039
	},
	[322181040] = {
		speaker = "阿齐姆",
		prefab_name = "",
		content = "多少有个盼头，能知道自己尽力了，花出去的力气也没白费，这样心里才踏实。",
		id = 322181040
	},
	[322181041] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "我记得我说过，你们有资格做的事就是少拖后腿。",
		id = 322181041
	},
	[322181042] = {
		speaker = "高尔",
		prefab_name = "",
		content = "是……",
		id = 322181042
	},
	[322181043] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "所以，我可没说远征不让你们跟着。",
		id = 322181043
	},
	[322181044] = {
		speaker = "",
		prefab_name = "",
		content = "人群中骤然爆发出一阵私语，冥王得意洋洋地听了一会儿，发现他们没有停下来的意思，又不悦地敲了敲地面。",
		id = 322181044
	},
	[322181045] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "但别说我没提醒过你们，自己的命自己管好，要是谁敢妨碍我——",
		id = 322181045
	},
	[322181046] = {
		speaker = "",
		prefab_name = "",
		content = "一些人喜出望外连连点头，一些人则苦笑着犹豫不决。冥王也没管人群怎样分成两拨，自顾自朝那些蛇形视骸出现的方向走去。",
		id = 322181046
	},
	[322182001] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "嘁，就知道用这些爬虫浪费我的时间。",
		id = 322182001
	},
	[322182002] = {
		speaker = "",
		prefab_name = "",
		content = "生魂在冥王前方掀起一弧气浪，锋锐的边沿撕开她面前最后几只视骸的躯体，随后炸开的气流将骸能扇向远处。",
		id = 322182002
	},
	[322182003] = {
		speaker = "",
		prefab_name = "",
		content = "冥王做了个深呼吸，抬头看到远方又有一群视骸在平台与坡道间一浪一浪地涌过来，直起身子冷哼一声。",
		id = 322182003
	},
	[322182004] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "小冥王，要不就到这里吧……",
		id = 322182004
	},
	[322182005] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "连阿波菲斯的影子都没看到，你不会已经撑不住了吧？",
		id = 322182005
	},
	[322182006] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "我不会……这里离基源层已经很近了，神能会受到抑制。",
		id = 322182006
	},
	[322182007] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "你看你，出了这么多汗，恢复的速度已经跟不上消耗的速度了。",
		id = 322182007
	},
	[322182008] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "担心我就免了，我可没弱到连这点压力都受不了……",
		id = 322182008
	},
	[322182009] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "那些跟过来的人类呢？他们不会走着走着死在路上了吧？",
		id = 322182009
	},
	[322182010] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "至少现在还不至于，源层的异变没有结束，他们能在这里存活，算是仅有的好消息了。",
		id = 322182010
	},
	[322182011] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "可要是继续往深处走，我也不确定会发生什么。",
		id = 322182011
	},
	[322182012] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哼，那就不关我的事了。早就提醒过他们，别拖我的后腿。",
		id = 322182012
	},
	[322182013] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "不过就这么傻兮兮地往前走确实不是办法。梅塞可，你知不知道阿波菲斯长什么样？",
		id = 322182013
	},
	[322182014] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "体型很大，如果遇到了应该很容易就能认出来。如果一定要描述——",
		id = 322182014
	},
	[322182015] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "一定要描述？",
		id = 322182015
	},
	[322182016] = {
		speaker = "",
		prefab_name = "",
		content = "梅塞可的话只说到一半。冥王扭头看向她，余光忽然注意到一侧的天空如同阴天放晴，渐渐亮了起来。",
		id = 322182016
	},
	[322182017] = {
		speaker = "",
		prefab_name = "",
		content = "冥王下意识望向光源，却看到天空中挂着一轮橙黄色的太阳。边缘放射状的光线和强烈的光晕刺眼得有些不自然，但光照在脸上的暖意却无比真实。",
		id = 322182017
	},
	[322182018] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……我们回表层了吗？",
