	},
	[322201008] = {
		speaker = "伊里伽尔",
		prefab_name = "1043ui_story",
		content = "可以的话还是以保住性命为前提……",
		id = 322201008
	},
	[322201009] = {
		speaker = "伊里伽尔",
		prefab_name = "1043ui_story",
		content = "奥西里斯带给你的录音，还没听吗？",
		id = 322201009
	},
	[322201010] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "为什么要听？",
		id = 322201010
	},
	[322201011] = {
		speaker = "伊里伽尔",
		prefab_name = "1043ui_story",
		content = "说不定里面有什么计策，毕竟是那位管理员给的。",
		id = 322201011
	},
	[322201012] = {
		speaker = "",
		prefab_name = "",
		content = "冥王将信将疑地打开奥西里斯交给她的终端，无须寻找，里面就只有一条录音而已。",
		id = 322201012
	},
	[322201013] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "他连我的情况都不知道，怎么可能有计策？",
		id = 322201013
	},
	[322201014] = {
		speaker = "",
		prefab_name = "",
		content = "不抱希望地摇了摇头，冥王看着这条录音，犹豫了一会儿，还是打开了它。",
		id = 322201014
	},
	[322201015] = {
		speaker = "",
		prefab_name = "",
		content = "冥王，我是#{nickname}#。",
		id = 322201015
	},
	[322201016] = {
		speaker = "",
		prefab_name = "",
		content = "抱歉，这几天没能找到你，现在只能用这样自说自话的方式问候。",
		id = 322201016
	},
	[322201017] = {
		speaker = "",
		prefab_name = "",
		content = "非常高兴听到你还活着的消息，也非常感谢你救了奥西里斯和伊里伽尔。",
		id = 322201017
	},
	[322201018] = {
		speaker = "",
		prefab_name = "",
		content = "该说真不愧是你吗……换成别人，很难想象能争取到这么乐观的结果。",
