	},
	[322201019] = {
		speaker = "",
		prefab_name = "",
		content = "我不知道你现在有什么计划或者想法，我也不知道你的境况，很难提供有效的建议。",
		id = 322201019
	},
	[322201020] = {
		speaker = "",
		prefab_name = "",
		content = "我只能说，你为我们做的已经够多了，无论你接下来想怎么做，我都会尊重你的选择。",
		id = 322201020
	},
	[322201021] = {
		speaker = "",
		prefab_name = "",
		content = "如果需要帮助，或者有什么想法，都可以告诉奥西里斯和伊里伽尔，或者可以去找科尔盖，他们也会全力支持你……",
		id = 322201021
	},
	[322201022] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "什么嘛……",
		id = 322201022
	},
	[322201023] = {
		speaker = "伊里伽尔",
		prefab_name = "1043ui_story",
		content = "冥王……",
		id = 322201023
	},
	[322201024] = {
