		content = "活得够酷——这就是他们的信念，哪怕有时候看上去很白痴，至少不会后悔。",
		id = 322202037
	},
	[322202038] = {
		speaker = "伊里伽尔",
		prefab_name = "1043ui_story",
		content = "我不知道你是以怎么样的信念活着。总之，应该不是随便说放弃的那一类吧。",
		id = 322202038
	},
	[322211001] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "这下彻底安静了。",
		id = 322211001
	},
	[322211002] = {
		speaker = "",
