	[322211019] = {
		speaker = "",
		prefab_name = "",
		content = "冥王瞥了眼地上破碎的生魂，摇摇头，懒得装腔作势，直接坐回了原处。图灵倒是没管冥王，同样看着生魂，神情中露出一丝诧异。",
		id = 322211019
	},
	[322211020] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "这是阿波菲斯打断的？",
		id = 322211020
	},
	[322211021] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "那总不能是我自己掰断的。",
		id = 322211021
	},
	[322211022] = {
		speaker = "",
		prefab_name = "",
		content = "图灵皱了皱眉，抬手将生魂引到他手中，仔细端详起来。冥王伸手想要把它抢回来，可忽然愣了愣，慢慢收回手。",
		id = 322211022
	},
	[322211023] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "喂……你不会是好心来帮我修权钥的吧？",
		id = 322211023
	},
	[322211024] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "这东西，我要带走。",
		id = 322211024
	},
	[322211025] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……哦，巴钦好像就是来抢生魂的，原来是你的命令。",
		id = 322211025
	},
	[322211026] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "可惜啊，晚来一步，现在已经是废品了。你要是这么喜欢收破烂，就拿去吧。",
		id = 322211026
	},
	[322211027] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "你似乎不理解它的价值。",
		id = 322211027
	},
	[322211028] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "是吗？你比我懂？那要不你跟我说说？",
		id = 322211028
	},
	[322211029] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "那就太繁琐了。",
		id = 322211029
	},
	[322211030] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "总之，感谢配合。",
		id = 322211030
	},
	[322211031] = {
		speaker = "",
		prefab_name = "",
		content = "冥王唤起气流，卷起一支弩箭，射向图灵。但威力实在过于羸弱，还没碰到图灵，也没见图灵有什么动作，弩箭便像是砸在钢铁上的玻璃，一寸寸碎裂开来。",
		id = 322211031
	},
	[322211032] = {
		speaker = "图灵",
		prefab_name = "4037ui_story",
		content = "这是什么意思？",
		id = 322211032
	},
	[322211033] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "意思是，不用谢，我可受不起。",
		id = 322211033
	},
	[322211034] = {
		speaker = "",
		prefab_name = "",
		content = "图灵思索片刻，点了点头，迈出步子的同时，身子微微摇晃了一下，也不见空间出现什么变化，他却已经消失了。",
		id = 322211034
	},
	[322211035] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……把生魂给他，真的没事吗？",
		id = 322211035
	},
	[322211036] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "不用担心我。就像你与奥西里斯没分开时，其实是住在心象房间里一样，就算没有生魂，我也不会消失。",
		id = 322211036
	},
	[322211037] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你也有个心象房间？",
		id = 322211037
	},
	[322211038] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "呵呵，你猜呢？",
		id = 322211038
	},
	[322211039] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……无所谓，我对参观别人家没兴趣。",
		id = 322211039
	},
	[322211040] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "那你知不知道图灵拿走生魂要干什么？",
		id = 322211040
	},
	[322211041] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "图灵的想法，我怎么猜得到呢？",
		id = 322211041
	},
	[322211042] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "唉，也是，智骸一个个脑子都不太正常。",
		id = 322211042
	},
	[322211043] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你继续讲故事吧，总不至于还有人跑到这儿来。",
		id = 322211043
	},
	[322211044] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "好呀。嗯……小冥王是不是没有去过凯米特？",
		id = 322211044
	},
	[322211045] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "啊？呃，没去过。",
		id = 322211045
	},
	[322211046] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "以后有机会，可一定要去看看。",
		id = 322211046
	},
	[322211047] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "乘一艘游船，顺着卢克索河慢慢走，你可以看到最壮美的沙漠和落日，还有最辉煌的城塞和庙宇。",
		id = 322211047
	},
	[322211048] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "如果嫌那些地方太远，也可以坐在河畔，与莎草和芦苇一起吹风，看白鹭和渔人在河上捕鱼。",
		id = 322211048
	},
	[322211049] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "到了黄昏，整个凯米特都会变成漂亮的琥珀色，太阳会落得很近，就好像它也想看看这个世界……",
		id = 322211049
	},
	[322211050] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "所以你是凯米特人？",
		id = 322211050
	},
	[322211051] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "嗯，如果你去过凯米特，看到我的衣服就能认出来了。",
		id = 322211051
	},
	[322211052] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……你不会是在挖苦我吧？你看我像是有机会去旅游的样子吗？",
		id = 322211052
	},
	[322211053] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "啊……会有这样的感觉吗？我只是想把我喜欢的东西分享给你。",
		id = 322211053
	},
	[322211054] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "算了，没事，反正去不了，听你讲讲也挺好。",
		id = 322211054
	},
	[322211055] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "但既然是故事，能不能讲点更有趣的？",
		id = 322211055
	},
	[322211056] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "好吧，那就讲讲阿波菲斯？",
		id = 322211056
	},
	[322211057] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你这跨度是不是有点大……",
		id = 322211057
	},
	[322211058] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "因为感觉像是你会感兴趣的话题嘛。",
		id = 322211058
	},
	[322211059] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "而且也不能说没有关联，因为阿波菲斯上一次出现就是在凯米特，没想到这次换到夏什瓦特了。",
		id = 322211059
	},
	[322211060] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "等等……为什么你对阿波菲斯这么熟悉？",
		id = 322211060
	},
	[322211061] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "讲故事总要有点悬念嘛，听完以后就知道了。",
		id = 322211061
	},
	[322211062] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "那时候，就像奥丁在艾因索菲建立了深空之眼，一位名字叫「拉」的原初修正者，在凯米特建立了一个修正者组织，叫作「晨昏塔」。",
		id = 322211062
	},
	[322211063] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "阿波菲斯出世的时候，科尔盖和晨昏塔都已经有过应对天灾种的经验，所以到场还算及时。",
		id = 322211063
	},
	[322211064] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "参战的人里，有不少你也算认识。像是休啊、塞尔凯特啊、奥西里斯……",
		id = 322211064
	},
	[322211065] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "啊？奥西里斯？她打阿波菲斯？",
		id = 322211065
	},
	[322211066] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "别小瞧奥西里斯哦~上个纪元她还是很强的，只是后来遭遇了几次重创，有些损伤在回到神域后都没法修复。",
		id = 322211066
	},
	[322211067] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哦……像是执明的眼睛那样。",
		id = 322211067
	},
	[322211068] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "是的，其中一次就是因为阿波菲斯。",
		id = 322211068
	},
	[322211069] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "为了速战速决，她在其他人的掩护下与阿波菲斯近身搏斗，虽然摧毁了骸能核心，但自己也受到严重的侵蚀。",
		id = 322211069
	},
	[322211070] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "好在拉用原初权能保住了她的性命，最后总算撑到了纪元重启。",
		id = 322211070
	},
	[322211071] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "拉的原初权能是什么？治病吗？",
		id = 322211071
	},
	[322211072] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "唔，也不能算错吧。准确地说，是操控生死。",
		id = 322211072
	},
	[322211073] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……操控什么？",
		id = 322211073
	},
	[322211074] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "不用这么惊讶啦，其实没有你想象得那么厉害。对视骸干涉的能力有限，其他场合，一般也做不到起死回生。",
		id = 322211074
	},
	[322211075] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你刚才是不是说了「一般」？",
		id = 322211075
	},
	[322211076] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "诞生与消亡是万事万物必然的过程，哪怕能干涉一时，也没法颠倒规律……啊，还是继续说阿波菲斯吧。",
		id = 322211076
	},
	[322211077] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "可大家都没想到，即便骸能核心被摧毁，阿波菲斯还是没有死。与一般的视骸不同，它的核心只是能量的核心，并不用来维持生命。",
		id = 322211077
	},
	[322211078] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "科尔盖突然被它袭击，伤亡很重。最后大家将它的躯体连同核心完全破坏，才算真正消灭了它。",
		id = 322211078
	},
	[322211079] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你……这么重要的事你怎么不早说？！让伊里伽尔带个话回去啊！",
		id = 322211079
	},
	[322211080] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "别紧张啦。这一点，梵天是知道的，只是没想到她会在这种时候离开夏什瓦特……",
		id = 322211080
	},
	[322211081] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "哦，那还行。她和管理员整天神秘兮兮地往地下室钻，谁知道在想什么鬼点子。",
		id = 322211081
	},
	[322211082] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……不对啊，这些事你怎么知道得这么清楚？你说的这些事，你也去了？",
		id = 322211082
	},
	[322211083] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "是啊，我也在场……故事到这里还没完呢。",
		id = 322211083
	},
	[322211084] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "就像我刚才说的，生死权能要干涉自然规律，消耗很大。可最近几个纪元盖亚危机加重，拉不得不频繁使用权能。",
		id = 322211084
	},
	[322211085] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "与阿波菲斯的战斗又是一轮损耗，回到晨昏塔后，终于还是发生了意外。",
		id = 322211085
	},
	[322211086] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "权能坏了？",
		id = 322211086
	},
	[322211087] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "原初权能是盖亚授予的权限，没有「坏掉」这一说。",
		id = 322211087
	},
	[322211088] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "只是生死权能比较特殊，接触了太多生命，解析了太多灵魂，赋予了太多生死……",
		id = 322211088
	},
	[322211089] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "久而久之，权能本身孕育出一道自我意识，也可以说是新的生命。",
		id = 322211089
	},
	[322211090] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "她从生死权能中诞生，自然可以操控权能，就开始和拉争抢，像个任性的、想要玩具的孩子，听不进别人说话。",
		id = 322211090
	},
	[322211091] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "拉不忍心扼杀这新生的小生命，只能拜托庚辰将她封印，希望未来能为她找到出路。",
		id = 322211091
	},
	[322211092] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "可是，上个纪元末，拉的生命结束了……因为一些缘故，生死权能连同那孩子，一同寄宿到了生魂当中……",
		id = 322211092
	},
	[322211093] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……喂，你在说什么？！",
		id = 322211093
	},
	[322211094] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "每种原初权能都很珍贵，盖亚越是危难，它们就越不可或缺。",
		id = 322211094
	},
	[322211095] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "拉不想坐视生死权能消失，所以想办法保住了自己最后一点意识，希望将来有机会逆天改命，起死回生。",
		id = 322211095
	},
	[322211096] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "可当那孩子苏醒以后，拉才发现，她变得成熟了不少，以前那些不愉快的经历，也都忘记了。",
		id = 322211096
	},
	[322211097] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "虽然偶尔还是会任性，会太敏感，可慢慢也学会了和身边的人相处，学会保护大家，有了大人的样子。",
		id = 322211097
	},
	[322211098] = {
		speaker = "梅塞可",
		prefab_name = "10131ui_story",
		content = "「如果现在尝试复活，她大概会消失吧……」\n所以拉没有打扰她，悄悄看着她成长，感觉也很有意思。",
		id = 322211098
	},
	[322211099] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……骗人的吧……",
		id = 322211099
	},
	[322211100] = {
		speaker = "",
		prefab_name = "",
		content = "冥王怔怔地看着眼前的人，已然失语。梅塞可微笑着，走到她旁边，怜爱地揉了揉她的脑袋。",
		id = 322211100
	},
	[322211101] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "如果可以，真想永远对你说谎呢。",
		id = 322211101
	},
	[322221001] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "……呵，这样就说得通了，为什么你会出现在这里，为什么我不是修正者，为什么你说我已经死了，又可以保住我的命……",
		id = 322221001
	},
	[322221002] = {
		speaker = "",
		prefab_name = "",
		content = "呆坐了好一会儿，冥王慢慢平静下来，忽然感觉有些荒唐，嗤笑一声，忍不住摇了摇头。",
		id = 322221002
	},
	[322221003] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "可你这不是在搞笑吗？",
		id = 322221003
	},
	[322221004] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "陪我玩了半天，说了一大堆好话，结果我只是个多余的。有意思吗？",
		id = 322221004
	},
	[322221005] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "没有生命是多余的，千万别这么想。",
		id = 322221005
	},
	[322221006] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "行了，用不着安慰我。",
		id = 322221006
	},
	[322221007] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "倒也正常，最开始就是这样……一直在吸收奥西里斯的神能，害她没法训练。",
		id = 322221007
	},
	[322221008] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你也看到她现在的实力了。要是没有我，她本来就用不着我保护，这我当然都知道……",
		id = 322221008
	},
	[322221009] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "小冥王……",
		id = 322221009
	},
	[322221010] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "啧，换个思路想想，情况是不是还变好了？",
		id = 322221010
	},
	[322221011] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "本来我以为我们都得死，现在至少你还有机会活……是这个意思吧？",
		id = 322221011
	},
	[322221012] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "嗯……",
		id = 322221012
	},
	[322221013] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "那已经不错啦。你就真心实意地感谢我吧。",
		id = 322221013
	},
	[322221014] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "就像管理员说的，如果换成别人，苏什那、巴钦、阿波菲斯……这样一个个打过来，早就变成灰了，哪有机会给你复活？",
		id = 322221014
	},
	[322221015] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "你要不现在复活得了。回表层大杀一通，危机解决，原初修正者回归，皆大欢喜。",
		id = 322221015
	},
	[322221016] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "哪有那么简单……我没法估算要花多长时间，也没有成功的把握。",
		id = 322221016
	},
	[322221017] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "而且那样你就会……你一点都不害怕吗？",
		id = 322221017
	},
	[322221018] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "怕不怕死的问题不是早就聊过了？",
		id = 322221018
	},
	[322221019] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "但我觉得小伊里说得没错，你不是会甘心认命的性格。",
		id = 322221019
	},
	[322221020] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "那怎么办……你要陪我等吗？等到阿波菲斯被干掉，等管理员或者谁过来找到我们，等他们想办法……",
		id = 322221020
	},
	[322221021] = {
		speaker = "",
		prefab_name = "",
		content = "掏出奥西里斯带来的终端，冥王拨了几个深空之眼的号码，结果自然是没有信号。",
		id = 322221021
	},
	[322221022] = {
		speaker = "",
		prefab_name = "",
		content = "她百无聊赖地打开那段录音，在地上刨了个小坑，把半截终端埋进去，就像是立了个装有扬声器的滑稽墓碑。",
		id = 322221022
	},
	[322221023] = {
		speaker = "",
		prefab_name = "",
		content = "……",
		id = 322221023
	},
	[322221024] = {
		speaker = "",
		prefab_name = "",
		content = "我只能说，你为我们做的已经够多了，无论你接下来想怎么做，我都会尊重你的选择。",
		id = 322221024
	},
	[322221025] = {
		speaker = "",
		prefab_name = "",
		content = "如果需要帮助，或者有什么想法，都可以告诉奥西里斯和伊里伽尔，或者可以去找科尔盖，他们也会全力支持你……",
		id = 322221025
	},
	[322221026] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "「如果需要帮助，可以告诉谁谁」……人类就喜欢这样，自己做不到的事还喜欢说得煞有介事，好像说两句不痛不痒的关心就仁至义尽了。",
		id = 322221026
	},
	[322221027] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "到时候你再跟他们讲一遍故事，问他们有什么主意，保证一问一个不吭声。",
		id = 322221027
	},
	[322221028] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "对他们这么没信心吗？",
		id = 322221028
	},
	[322221029] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "连你这个「操控生死」的原初都没招了，最好别太高看他们。最多再像这样说两句好话……",
		id = 322221029
	},
	[322221030] = {
		speaker = "",
		prefab_name = "",
		content = "冥王左右看看，像是要找个趁手的东西把那聒噪的终端砸烂，可似乎已经播完的录音，经过稍显长久的沉默后，忽然又传出了声音。",
		id = 322221030
	},
	[322221031] = {
		speaker = "",
		prefab_name = "",
		content = "……接下来的话，可能会有点奇怪。但我不确定还有没有机会当面跟你说，毕竟后面会发生什么，我也没底。",
		id = 322221031
	},
	[322221032] = {
		speaker = "",
		prefab_name = "",
		content = "我明白，你对深空之眼还有芥蒂，那些手术，对你的质疑……确实伤害过你，都是对你的亏欠。",
		id = 322221032
	},
	[322221033] = {
		speaker = "",
		prefab_name = "",
		content = "作为综合科的管理员，我不想逃避这个问题，所以不会自大到用深空之眼的规章制度苛求你，也做好了你可能想要离开深空之眼的准备。",
		id = 322221033
	},
	[322221034] = {
		speaker = "",
		prefab_name = "",
		content = "但是从个人感情的角度，无论是我，奥西里斯，薇儿……这几个月相处下来，大家都是真心希望你能成为我们的同伴。",
		id = 322221034
	},
	[322221035] = {
		speaker = "",
		prefab_name = "",
		content = "这回突然和你分开，我们都很不适应，尤其是奥西里斯。我们也都很担心你，不知道你情况如何，应对那么多强敌有没有受伤。",
		id = 322221035
	},
	[322221036] = {
		speaker = "",
		prefab_name = "",
		content = "毕竟你做事大大咧咧的，战斗的时候也总是很拼命，怎么想都让人放心不下。",
		id = 322221036
	},
	[322221037] = {
		speaker = "",
		prefab_name = "",
		content = "但也正因为这样，实话实说，我一直觉得，你能够成为大家榜样。强大，善良，负责，懂得保护别人，也有自己的个性和想法。",
		id = 322221037
	},
	[322221038] = {
		speaker = "",
		prefab_name = "",
		content = "我觉得，对修正者来说，力量固然重要，但更宝贵的，是永远保持清醒和明确的目标，永远不会迷茫、不会犹豫的信念。",
		id = 322221038
	},
	[322221039] = {
		speaker = "",
		prefab_name = "",
		content = "奥丁是这样，庚辰是这样。像薇儿这样的还在成长，算是慢慢学到了一些吧……而你，其实早就已经走在大多数人前面了。",
		id = 322221039
	},
	[322221040] = {
		speaker = "",
		prefab_name = "",
		content = "你可能不知道，深空之眼里有不少人听说过你，但一直没机会和你见面，都在说想要「瞻仰你的力量」呢……",
		id = 322221040
	},
	[322221041] = {
		speaker = "",
		prefab_name = "",
		content = "所以，无论如何，只要你愿意信任我们……试着信任一下一直信任着你的我们，那么深空之眼依然是你的家。",
		id = 322221041
	},
	[322221042] = {
		speaker = "",
		prefab_name = "",
		content = "这里也有很多人……在等你回家。",
		id = 322221042
	},
	[322221043] = {
		speaker = "冥王",
