	},
	[322221047] = {
		speaker = "冥王",
		prefab_name = "1111ui_story",
		content = "肉麻死了，简直跟你一个德行。",
		id = 322221047
	},
	[322221048] = {
		speaker = "拉",
		prefab_name = "10131ui_story",
		content = "你是怎么想的呢？对于深空之眼，还有那里的人。",
