	},
	[322221059] = {
		speaker = "",
		prefab_name = "",
		content = "冥王拍拍屁股站起来，望着阿波菲斯消失的方向。在笼罩着源层的极致寂静中，她却仿佛听到了利刃扫荡的风啸和炮火爆裂的轰鸣。",
		id = 322221059
	},
	[322221060] = {
