	},
	[322251007] = {
		speaker = "我",
		prefab_name = "",
		content = "我不知道……好吧，准确地说，这座岛不是监察者告诉我的。",
		id = 322251007
	},
	[322251008] = {
		speaker = "我",
		prefab_name = "",
		content = "是薇儿说的那个「小院长」给我传的话。找到诺尔薇，找到监察者，他们可能会帮我解决失忆的问题。",
		id = 322251008
	},
	[322251009] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "你认识诺尔薇？",
		id = 322251009
	},
	[322251010] = {
		speaker = "我",
		prefab_name = "",
		content = "失忆以前应该认识吧，薇儿说可能是我姐姐什么的……你知道她？",
		id = 322251010
	},
	[322251011] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "第一纪元见过一面。她苏醒比我们早，我们对她了解不多。",
		id = 322251011
	},
	[322251012] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "只知道她那一手操控时间的能力，我们六个原初拿她都没办法。",
		id = 322251012
	},
	[322251013] = {
		speaker = "",
		prefab_name = "",
		content = "我回过头盯着梵天，确信她说这句话没有夸大的成分，见了鬼似地摇摇头。",
		id = 322251013
	},
	[322251014] = {
		speaker = "我",
		prefab_name = "",
		content = "什么叫拿她没办法，别告诉我她是敌人。",
		id = 322251014
	},
	[322251015] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "那不至于。当时以为她和我们一样也是原初，想邀请她一起行动，结果被她拒绝了。",
		id = 322251015
	},
	[322251016] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "忘记怎么聊的了，反正想问清她的底细，她又不肯说。宙斯先和她打了一架，没打过，天照和庚辰想留住她，也没成功。",
		id = 322251016
	},
	[322251017] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "那怎么办呢？只能放她走。后来我们就没再见过她了。",
		id = 322251017
	},
	[322251018] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "但至少她是修正者，和我们也没动真格，算不上敌人。",
		id = 322251018
	},
	[322251019] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "……哎，你说的「标志」，是不是那个？",
		id = 322251019
	},
	[322251020] = {
		speaker = "",
		prefab_name = "",
		content = "听到梵天的提醒，我从对那位素未谋面的「姐姐」的震惊中回过神，但也没有多问。毕竟按薇儿所说我与诺尔薇的关系，她越强对我越有利。",
		id = 322251020
	},
	[322251021] = {
		speaker = "",
		prefab_name = "",
		content = "梵天指着沙滩上一块不起眼的黑色凸起，乍一看像是一块散落的鹅卵石。她比了个打枪的手势，一发空气炮从她指尖射出，扫开那块石头周围的一大片沙粒。",
		id = 322251021
	},
	[322251022] = {
		speaker = "",
		prefab_name = "",
		content = "只有那块石头，以及周围被埋在沙滩深处的另外十四颗石头，在风暴中纹丝不动。",
		id = 322251022
	},
	[322251023] = {
