	},
	[322251029] = {
		speaker = "",
		prefab_name = "",
		content = "我原地两次向后转，梵天则是悬空飘浮转了一圈，同时戒备地捏住了权钥。然而四周并没有什么动静。",
		id = 322251029
	},
	[322251030] = {
		speaker = "",
		prefab_name = "",
		content = "感受到她责问的眼神，我抿了抿嘴，刚想解释，踩在地面上的实感骤然消失。我们还没看清怎么回事，便被一股不像是重力的牵引力拉着坠落下去。",
		id = 322251030
	},
	[322251031] = {
		speaker = "",
		prefab_name = "",
		content = "极度错乱的空间感让我甚至没法判断自己在往哪里移动，稳定下来以后也不知道已经过了多久。",
		id = 322251031
