	[322251098] = {
		speaker = "",
		prefab_name = "",
		content = "她只能平躺着，眼看晦暗的天幕向大地沉降，远方山峦的背面回荡着无名巨兽沉厚绵长的哀鸣，仿佛世界崩落的挽歌。",
		id = 322251098
	},
	[322251099] = {
		speaker = "？？？",
