	},
	[322251129] = {
		speaker = "",
		prefab_name = "",
		content = "我张了张嘴，却无从反驳。毕竟失去的记忆还没有被完全找回，我没法保证自己过去是怎样的人，又经历过什么。",
		id = 322251129
	},
	[322251130] = {
