	},
	[322261027] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "他失忆了。",
		id = 322261027
	},
	[322261028] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "什么？！",
		id = 322261028
	},
	[322261029] = {
		speaker = "",
		prefab_name = "",
		content = "怀信的反应比我预想中还大，他的眼神与其说警惕，更像是失望与悲伤。我没法分辨这种情绪的来源，只是觉得有些熟悉，让我第一次对「失忆」的态度产生了偏移。",
		id = 322261029
	},
	[322261030] = {
		speaker = "我",
		prefab_name = "",
		content = "是很严重的事吗？",
		id = 322261030
	},
	[322261031] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "……至少你还活着。",
		id = 322261031
	},
	[322261032] = {
		speaker = "我",
		prefab_name = "",
		content = "是吗……",
		id = 322261032
	},
	[322261033] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这么说可能有些不近人情，但你的记忆关系到的并不只有你的个人得失。可以说说吗，你还记得什么？",
		id = 322261033
	},
	[322261034] = {
		speaker = "",
		prefab_name = "",
		content = "我摊了摊手，原本就没有隐瞒的打算，简单讲了一遍我在艾因索菲遇袭失忆，最后加入深空之眼的过程。",
		id = 322261034
	},
	[322261035] = {
		speaker = "我",
		prefab_name = "",
		content = "我能想起来的细节不多，以及更久远的……我知道还有些更重要的事「存在过」，但我实在没有头绪。",
		id = 322261035
	},
	[322261036] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "你怎么会被视骸袭击？索菲娅留给你的修正者呢？",
		id = 322261036
	},
	[322261037] = {
		speaker = "我",
		prefab_name = "",
		content = "谁是索菲娅？留给我的……你是说诺尔薇？",
		id = 322261037
	},
	[322261038] = {
		speaker = "",
		prefab_name = "",
		content = "怀信对我的第二个疑问没有反应，因为当我说完第一句话，他已经有些失神，最后无奈地叹了口气，我只看得出他眼神中惋惜与惆怅。",
		id = 322261038
	},
	[322261039] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "是吗，你连索菲娅都忘了……",
		id = 322261039
	},
	[322261040] = {
		speaker = "",
		prefab_name = "",
		content = "如果说遗忘是一种罪过，怀信给我定的罪大概不轻。可除了听到「索菲娅」时脑海中下意识构想出的模糊印象外，我实在想不起更多。",
		id = 322261040
	},
	[322261041] = {
		speaker = "",
		prefab_name = "",
		content = "我甚至没法判断这模糊的印象究竟指向一个具体的人，还是我对这个名字的刻板理解，亦或只是联想到了薇儿说的「圣索菲娅医护中心」。",
		id = 322261041
	},
	[322261042] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "……大概这就是命啊。盖亚外夭折的事，到了盖亚里，又岂会忽然变得顺利？",
		id = 322261042
	},
	[322261043] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "议会失联，你又失忆，依托比尔轴的状况还不见好转……",
		id = 322261043
	},
	[322261044] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "监察者到底怎么了？你有办法找到它们吗？",
		id = 322261044
	},
	[322261045] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "议会切断了它和表层的连接，界外领域广袤无边，现在恐怕没人能找到了。",
		id = 322261045
	},
	[322261046] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我最后接到的消息，只提到议会控制的部分权限被窃取，出于安全考虑，不得不紧急断联。",
		id = 322261046
	},
	[322261047] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "按主轴世界的时间来算，已经两百多年了。「权限被窃取」，我至今不知道发生了什么。",
		id = 322261047
	},
	[322261048] = {
		speaker = "我",
		prefab_name = "",
		content = "窃取监察者的权限？谁能做到这种事？",
		id = 322261048
	},
	[322261049] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "如果能查到始作俑者，议会也不用出此下策。",
		id = 322261049
	},
	[322261050] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这已经不是第一次发生了……上次的结果你们都很熟悉，就是视骸的出现。所以窃取权限的祸首，很可能就是视骸的源头。",
		id = 322261050
	},
	[322261051] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "……",
		id = 322261051
	},
	[322261052] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "所以，你来这里，是希望能找回你遗失的记忆？",
		id = 322261052
	},
	[322261053] = {
		speaker = "我",
		prefab_name = "",
		content = "能想到的办法都试过了，各种数据库，甚至是往世书……最后也没查到关于我的什么事。",
		id = 322261053
	},
	[322261054] = {
		speaker = "我",
		prefab_name = "",
		content = "我想我应该没找错人？听上去你很了解我。",
		id = 322261054
	},
	[322261055] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "了解吗？曾经算是吧，至于现在……",
		id = 322261055
	},
	[322261056] = {
		speaker = "",
		prefab_name = "",
		content = "怀信苦笑一声，摇了摇头，背着手走到操作台边，调出一张照片。",
		id = 322261056
	},
	[322261057] = {
		speaker = "",
		prefab_name = "",
		content = "那是一张两个人的合照，背景是一座排满会议桌椅的大礼堂。其中一人是怀信，另一个人的样貌和我很像，年纪比我稍大些。",
		id = 322261057
	},
	[322261058] = {
		speaker = "",
		prefab_name = "",
		content = "两人都穿着正装，公务会面似地保持着握手的姿势，同时朝镜头的方向微微侧身，可以看到他们右臂佩戴的袖章上都印着与监察者议会几乎一模一样的标志。",
		id = 322261058
	},
	[322261059] = {
		speaker = "我",
		prefab_name = "",
		content = "这是……我？",
		id = 322261059
	},
	[322261060] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "七零年，盖亚环境稳定性测试的技术研讨会。",
		id = 322261060
	},
	[322261061] = {
		speaker = "我",
		prefab_name = "",
		content = "你说的是……进入盖亚之前？",
		id = 322261061
	},
	[322261062] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "是啊，原本以为再见面的时候免不了追忆往昔，就留了张照片作个念想。没想到，世事难料。",
		id = 322261062
	},
	[322261063] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "项目代号「解药」的骨干，「星骸」技术攻关小组的负责人，中央科学院最年轻的机械工程与自动化专家——",
		id = 322261063
	},
	[322261064] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "没错，右边这个就是你。不过那时候你还没开始研究星骸，正忙着设计盖亚的主体框架和传动系统。",
		id = 322261064
	},
	[322261065] = {
		speaker = "我",
		prefab_name = "",
		content = "我……参与了盖亚的开发？",
		id = 322261065
	},
	[322261066] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "难怪执明经常说你有搞科研的气质。",
		id = 322261066
	},
	[322261067] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "岂止参与。如果不是因为研究星骸，你作为盖亚技术组的核心成员，最后加入监察者议会也不是不可能。",
		id = 322261067
	},
	[322261068] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "毕竟整个盖亚计划的技术总负责人，就是你的……唔，论认识的时间，算是大学同学——索菲娅。",
		id = 322261068
	},
	[322261069] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "你和她互相知根知底，在科学院搭档了很长时间。她没理由把你最擅长领域的工作交给别人。",
		id = 322261069
	},
	[322261070] = {
		speaker = "我",
		prefab_name = "",
		content = "所以，她是监察者的一员？",
		id = 322261070
	},
	[322261071] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "如果是，和你联系的就不会是我了。这就是我并不了解你，或者说「你们」的地方。",
		id = 322261071
	},
	[322261072] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "从盖亚启动开始，你们在盘算什么，对于星骸的研究……这是只属于你们两个人的道路。",
		id = 322261072
	},
	[322261073] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我并不知道她在哪里，就像我不知道这些年你在哪里一样。",
		id = 322261073
	},
	[322261074] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我能告诉你的是，你必须要找到她，只有她才能帮你，也只有你才能帮她，从大学开始直到盖亚启动，你们一直都是这样……",
		id = 322261074
	},
	[322261075] = {
		speaker = "",
		prefab_name = "",
		content = "我不知道该怎样接话，觉得心里有些发堵。「索菲娅」——失去的记忆就像是一团巨大的真空，这个名字在真空的中央用力呼喊。",
		id = 322261075
	},
	[322261076] = {
		speaker = "",
		prefab_name = "",
		content = "我忽然意识到了它的存在，甚至身体都回忆起了它存在时的知觉，然而可触及的现实却只有一片虚无，让人无从下手。",
		id = 322261076
	},
	[322261077] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "你说的「星骸」，那是什么东西？",
		id = 322261077
	},
	[322261078] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "……是一种纳米机器人，也是人类被逼到这种境地的罪魁祸首。",
		id = 322261078
	},
	[322261079] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "没人知道它们到底是什么，能量来源是什么，从哪里来，为什么要杀戮，要破坏……",
		id = 322261079
	},
	[322261080] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "听上去和视骸很像。",
		id = 322261080
	},
	[322261081] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "是啊，议会也猜想可能是星骸进入了盖亚。「视骸」这个名字，就是来自「星骸」。",
		id = 322261081
	},
	[322261082] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "但盖亚是数据世界，我们之所以躲进这里，就是因为星骸理论上不具备主动接入人类网络的能力，所以这个猜想慢慢被推翻了。",
		id = 322261082
	},
	[322261083] = {
		speaker = "我",
		prefab_name = "",
		content = "你敢肯定？星骸就是视骸，听上去很合理。",
		id = 322261083
	},
	[322261084] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我可不会怀疑这个。因为这是你的研究成果。",
		id = 322261084
	},
	[322261085] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "七二年，我们捕获到一只特殊的星骸个体，没有攻击欲望，但内部一直保持着活跃的能量运动。",
		id = 322261085
	},
	[322261086] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "于是科学院找到了最擅长这类研究的你，希望你能破解星骸的秘密。但星骸增殖和爆发的形势太恶劣，留给你的时间不算多。",
		id = 322261086
	},
	[322261087] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "当时包括你的研究在内，还有几个拯救文明的项目在同时进行。然而进度最快的还是盖亚计划，通过环境稳定性测试，就意味着随时可以启动。",
		id = 322261087
	},
	[322261088] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "再后来，战局越来越糟糕，迫于拖到人类全灭的压力，委员会废止了其他所有方案，选择了盖亚。",
		id = 322261088
	},
	[322261089] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我不知道你进入盖亚具体的计划，只是索菲娅说，如果你能在盖亚里完成对星骸的研究，人类有了反攻的办法，就不用在虚拟世界里苟延残喘了。",
		id = 322261089
	},
	[322261090] = {
		speaker = "我",
		prefab_name = "",
		content = "……回到现实吗？",
		id = 322261090
	},
	[322261091] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "不是现实，是我们的家园，永远都是。",
		id = 322261091
	},
	[322261092] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "盖亚启动得急，存储与运行方面的优化还不完善，一个纪元至多只能维持四百年。",
		id = 322261092
	},
	[322261093] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这一点，你们几位原初修正者应该都知道。",
		id = 322261093
	},
	[322261094] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "……是，但这是禁止交流的事项。",
		id = 322261094
	},
	[322261095] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "不用你们挑明，科尔盖内部早晚也会察觉。",
		id = 322261095
	},
	[322261096] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "比起故土，比起我们还没来得及探索的、真正的星辰大海，盖亚说到底，只是一时的妥协和忘却罢了。",
		id = 322261096
	},
	[322261097] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "权宜之计过后，总要有新的打算。没人知道哪个方向通往未来，但至少我们不会否认尝试开辟新道路的努力。",
		id = 322261097
	},
	[322261098] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我在这里留下一道意识备份，就是等你带着「解药」过来，用切实可行的方案说服科尔盖，该从盖亚走出去了。",
		id = 322261098
	},
	[322261099] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "哪怕我不知道你的结论，哪怕结果未必理想……人类，文明，未来，都在等你的答案。",
		id = 322261099
	},
	[322261100] = {
		speaker = "",
		prefab_name = "",
		content = "「我的答案」吗……",
		id = 322261100
	},
	[322261101] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "如果你只是失忆，研究的成果还在，等你恢复记忆，总有继续这项事业的机会。",
		id = 322261101
	},
	[322261102] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "大概没有别人知道你的计划和成果。只能想办法完全恢复你的记忆了。",
		id = 322261102
	},
	[322261103] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "……也对，眼前还有更需要解决的问题。等你完全恢复记忆，以前的事总会有着落。",
		id = 322261103
	},
	[322261104] = {
		speaker = "我",
		prefab_name = "",
		content = "对了，说到我的过去，还有个需要解释清楚的问题……",
		id = 322261104
	},
	[322261105] = {
		speaker = "",
		prefab_name = "",
		content = "我看向身边的梵天，她终于从沉思中抬起头，眯起眼睛盯住我。",
		id = 322261105
	},
	[322261106] = {
		speaker = "我",
		prefab_name = "",
		content = "我进入盖亚的时候留下了一条报错记录，似乎是灵魂数据投放出了问题。",
		id = 322261106
	},
	[322261107] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "很正常，你要瞒着议会在盖亚里研究星骸，灵魂数据附带的屏蔽和防护不计其数，当然会报错。",
		id = 322261107
	},
	[322261108] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "但这种小错误数不胜数，只要没有诱发更大的问题，盖亚和议会都不会单独筛查。",
		id = 322261108
	},
	[322261109] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "不过局面到了这一步……老弟啊，如果能找回议会，恢复最高权限，就别在乎以前那些分歧了。",
		id = 322261109
	},
	[322261110] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "经过这次断联，议会应该会对盖亚的稳定性产生质疑。如果你能拿出收益更高的方案，未尝没有合作的可能。",
		id = 322261110
	},
	[322261111] = {
		speaker = "我",
		prefab_name = "",
		content = "我倒是没有负担，毕竟听你说下来，我和监察者没有太大的矛盾。",
		id = 322261111
	},
	[322261112] = {
		speaker = "我",
		prefab_name = "",
		content = "不如说最好现在就有能联系上他们的办法。否则真不知道天灾种要怎么解决……",
		id = 322261112
	},
	[322261113] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "天灾种又出现了？！",
		id = 322261113
	},
	[322261114] = {
		speaker = "",
		prefab_name = "",
		content = "终于把话题拐回到正轨上，梵天看上去也接受了我没有嫌疑的结果，于是我将智骸与天灾种的情况简要叙述了一遍。",
		id = 322261114
	},
	[322261115] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "人形视骸，拥有智能，这怎么可能？",
		id = 322261115
	},
	[322261116] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "重点是这个吗？",
		id = 322261116
	},
	[322261117] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "唉，你们还没转过弯来。",
		id = 322261117
	},
	[322261118] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "文艺作品里经常会想象其他种族可以幻化成人类的样子，但那只是以人类视角讲故事，图方便的做法而已，哪里是理所当然的事？",
		id = 322261118
	},
	[322261119] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "站在生物进化的角度，如果视骸族群内部形成了某种独特的思维和语言系统，这很正常。哺乳类、鸟类、昆虫……自然规律本就如此。",
		id = 322261119
	},
	[322261120] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "可这跟人类有什么关系？它们有什么理由放弃原来的形体，去使用人类的身体结构和语言系统？又是怎么做到的？",
		id = 322261120
	},
	[322261121] = {
		speaker = "我",
		prefab_name = "",
		content = "难道是灰烬？",
		id = 322261121
	},
	[322261122] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "灰烬？",
		id = 322261122
	},
	[322261123] = {
		speaker = "我",
		prefab_name = "",
		content = "推测是一种让视骸变成智骸的物质，但来历不明。说起智骸和普通视骸的区别，现在也只能想到这个了。",
		id = 322261123
	},
	[322261124] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "那可要好好查一查灰烬的来历。你这么说，这东西有可能跟议会被窃取的权限有关系。",
		id = 322261124
	},
	[322261125] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "要知道，一切关于人类的机理，都属于盖亚的底层逻辑，为的就是确保「人类永远是人类，只有人类是人类」。",
		id = 322261125
	},
	[322261126] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "恰好是议会无法履职的时候，这些东西混进了人类社会。很难相信只是巧合。",
		id = 322261126
	},
	[322261127] = {
		speaker = "？？？",
		prefab_name = "",
		content = "怎么，人类就这么排外？",
		id = 322261127
	},
	[322261128] = {
		speaker = "",
		prefab_name = "",
		content = "第四个人的声音从我与梵天的身后传来。我们几乎同时取出武器转过身，看清来者的身影后，神情渐渐变得凝重。",
		id = 322261128
	},
	[322261129] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这位是？",
		id = 322261129
	},
	[322261130] = {
		speaker = "我",
		prefab_name = "",
		content = "智骸，克罗塞尔。",
		id = 322261130
	},
	[322261131] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "喂喂喂，火气那么大干什么？门口就摆着几颗石头，又没说不让谁进来。",
		id = 322261131
	},
	[322261132] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "帕瓦呢？",
		id = 322261132
	},
	[322261133] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "她没事，交易愉快。你不用怪她，反正她硬要拦我也讨不到好，不如让我进来参观一下。",
		id = 322261133
	},
	[322261134] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "在你面前我就不玩虚张声势的把戏了。你应该能看出来，这只是一具替身人偶，就算杀了我也无济于事。",
		id = 322261134
	},
	[322261135] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "所以为什么不聊聊呢？我可最喜欢聊天了，尤其是在这种场合。",
		id = 322261135
	},
	[322261136] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "往世书、第一纪元、监察者……啊~这么多秘密近在眼前，谁能忍得住好奇心呢？",
		id = 322261136
	},
	[322261137] = {
		speaker = "我",
		prefab_name = "",
		content = "你为什么觉得我们会告诉你。",
		id = 322261137
	},
	[322261138] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "因为你们也有问题想问我，不是吗？",
		id = 322261138
	},
	[322261139] = {
		speaker = "",
		prefab_name = "",
		content = "我和梵天对视一眼，先后放下了武器。克罗塞尔夸张地张开双臂，像是对我们的态度表示欢迎。",
		id = 322261139
	},
	[322261140] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "我只有一个问题——",
		id = 322261140
	},
	[322261141] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "真正控制盖亚的，到底是什么？",
		id = 322261141
	},
	[322261142] = {
		speaker = "我",
		prefab_name = "",
		content = "就在你眼前，这不是明知故问？",
		id = 322261142
	},
	[322261143] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "呵呵，来得晚可不代表我好糊弄。",
		id = 322261143
	},
	[322261144] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "现在阿波菲斯已经复活，监察者却还没现身。原本我对他们失联的情报还有些质疑，现在看来果然是这样。",
		id = 322261144
	},
	[322261145] = {
		speaker = "",
		prefab_name = "",
		content = "听到阿波菲斯复活的消息，我忍不住看了眼梵天，她却没有反应，或说更像是有些走神，注意力明显不在克罗塞尔身上。",
		id = 322261145
	},
	[322261146] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "真正「控制盖亚」的，可不是无所谓在与不在的「使用者」。",
		id = 322261146
	},
	[322261147] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "盖亚的算力富余得很。如果监察者铁了心要对付视骸，那为所有修正者都赋予原初甚至更高的实力，还怕解决不了问题？",
		id = 322261147
	},
	[322261148] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "但你们没有那么做。唯一的解释就是，这不在你们的能力范围内。",
		id = 322261148
	},
	[322261149] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "哎呀，到底谁是提问方？如果你们不想先回答，那换你们问好了。",
		id = 322261149
	},
	[322261150] = {
		speaker = "我",
		prefab_name = "",
		content = "你复活天灾种到底想干什么？图灵手下到底还有多少智骸？",
		id = 322261150
	},
	[322261151] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "谁让你一次问两个问题……唉，不过看在你们态度还行的份上，我就吃点亏吧。",
		id = 322261151
	},
	[322261152] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "先说后面那个问题，答案是我也不知道。",
		id = 322261152
	},
	[322261153] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "图灵从来没把「启示者」当成一个组织，准确地说，大家都只是「认识他」而已。",
		id = 322261153
	},
	[322261154] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "像巴钦那样，愿意追随他一起行动的，就经常有机会和你们打照面。也有像我这样的，合作，然后各取所需。",
		id = 322261154
	},
	[322261155] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "当然了，也有些拒绝交流或者不听话的，图灵不会强迫他们做什么，只要别挡他的路就行。",
		id = 322261155
	},
	[322261156] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "啊~你刚才是不是松了口气？是不是在想，原来这些家伙是一盘散沙，威胁比想象中要小呢？",
		id = 322261156
	},
	[322261157] = {
		speaker = "我",
		prefab_name = "",
		content = "我们会做好最坏的预期和准备。",
		id = 322261157
	},
	[322261158] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "无所谓。打打杀杀的事，我多半不会参与就是了。",
		id = 322261158
	},
	[322261159] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "然后是天灾种，这也没什么可隐瞒的……我研究天灾种，只是为了寻找调用更多算力的方法。",
		id = 322261159
	},
	[322261160] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "无论是人类的灵魂数据，还是盖亚的功能系统，算力怎样分配给它们，有没有可能为我所用……",
		id = 322261160
	},
	[322261161] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "结果又回到我刚才的问题了，明明盖亚还有大量闲置算力，为什么没人有权调用？谁能调用？",
		id = 322261161
	},
	[322261162] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "你们应该能明白吧？在盖亚里，谁掌握了全部的算力，谁就能支配一切啊……",
		id = 322261162
	},
	[322261163] = {
		speaker = "我",
		prefab_name = "",
		content = "……你在夏什瓦特搞出那么多祸端，只是为了这个？",
		id = 322261163
	},
	[322261164] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "如果你在否认我研究的价值，我可不是一点脾气都没有的。",
		id = 322261164
	},
	[322261165] = {
		speaker = "我",
		prefab_name = "",
		content = "为什么？如果你只是为了研究，把表层弄得一团糟对你有什么好处？",
		id = 322261165
	},
	[322261166] = {
		speaker = "我",
		prefab_name = "",
		content = "混乱的结果只有崩溃和毁灭。盖亚毁了，你还能存在吗？你的研究又有什么意义？",
		id = 322261166
	},
	[322261167] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "崩溃和毁灭？不见得吧。",
		id = 322261167
	},
	[322261168] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "王座只是一把被权力和秩序架上天的椅子，而混乱就是通向它的阶梯。",
		id = 322261168
	},
	[322261169] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "人们看不清王座上的景象，被它居高临下的威严吓得抬不起头。",
		id = 322261169
	},
	[322261170] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "可只要靠近几步，你就会看清，混乱的根源，正是王座上的人过于孱弱。",
		id = 322261170
	},
	[322261171] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "能阻止崩溃和毁灭的，并不是逃避混乱，而是那个在混乱之中登上王座的人，施予的新权力，建立的新秩序。",
		id = 322261171
	},
	[322261172] = {
		speaker = "",
		prefab_name = "",
		content = "走到穹顶中央投下的一片光亮下，克罗塞尔抬起头，望着上方不知通向何处的混沌，露出志得意满的笑容。",
		id = 322261172
	},
	[322261173] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "所以，接下来就是赛跑环节了。",
		id = 322261173
	},
	[322261174] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "……没用的，告诉你也无妨，没人能控制盖亚。",
		id = 322261174
	},
	[322261175] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "是吗？可就算人类征服不了宇宙，也总有仰望星空的梦想家。",
		id = 322261175
	},
	[322261176] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "该你们了，回答问题吧。",
		id = 322261176
	},
	[322261177] = {
		speaker = "",
		prefab_name = "",
		content = "我和梵天也看向怀信，毕竟「盖亚并非完全受监察者控制」这件事，就连我们也是第一次听说。",
		id = 322261177
	},
	[322261178] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我只知道……那是一把「钥匙」。",
		id = 322261178
	},
	[322261179] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "盖亚使用的技术，人类开发的只占一小部分，其余都是黑箱，我们只找到了开启它的钥匙。",
		id = 322261179
	},
	[322261180] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "钥匙后面的，究竟是王座还是深渊……你真的看清了吗？",
		id = 322261180
	},
	[322261181] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "嗯？",
		id = 322261181
	},
	[322261182] = {
		speaker = "",
		prefab_name = "",
		content = "实验舱忽然发出一阵急促的警报，克罗塞尔插入的密钥自动弹出，帕尔瓦蒂按下控制台上结束警报的按钮，地下室才消停下来。",
		id = 322261182
	},
	[322261183] = {
		speaker = "",
		prefab_name = "",
		content = "坐在一旁椅子上的克罗塞尔睁开眼睛，发了会儿呆，摇了摇头，起身走向门外。",
		id = 322261183
	},
	[322261184] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "结束了？",
		id = 322261184
	},
	[322261185] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "密钥失效了。没有往世书验证，单凭我的记忆来复制，果然还是差点意思。",
		id = 322261185
	},
	[322261186] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "真是的……才刚聊到最有趣的部分呢。",
		id = 322261186
	},
	[322261187] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "聊？",
		id = 322261187
	},
	[322261188] = {
		speaker = "克罗塞尔",
		prefab_name = "10103ui_story",
		content = "想要我跟你解释，那就是另外的价钱了。",
		id = 322261188
	},
	[322261189] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "不想，你走吧。",
		id = 322261189
	},
	[322261190] = {
		speaker = "",
		prefab_name = "",
		content = "克罗塞尔耸耸肩，好像并不打算带走那把失效的密钥，就像是在博物馆里走马观花的访客，空着双手走出了大门。",
		id = 322261190
	},
	[322261191] = {
		speaker = "",
		prefab_name = "",
		content = "帕尔瓦蒂默默站在原地。直到在弥楼衍外墙摄像头的监控画面中看到克罗塞尔离开，才长长舒了口气，仰头瘫倒进椅子里。",
		id = 322261191
	},
	[322261192] = {
		speaker = "",
		prefab_name = "",
		content = "身后庞大的机器仍在运转，能量流过各种精密元件发出的细微声响如同助眠的白噪音，让她眼前的穹顶显得空旷起来。",
		id = 322261192
	},
	[322261193] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "会讲道理的人，真好——",
		id = 322261193
	},
	[322261194] = {
		speaker = "",
		prefab_name = "",
		content = "但穹顶上装满了各式各样的仪器，绝大多数都是为了「往世回廊」专门开发，独此一份，有的甚至连名称都没有。",
		id = 322261194
	},
	[322261195] = {
		speaker = "",
		prefab_name = "",
		content = "帕尔瓦蒂认不全这些设备，她知道初来乍到的克罗塞尔八成也认不全。",
		id = 322261195
	},
	[322261196] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "……真好骗啊。",
		id = 322261196
	},
	[322271001] = {
		speaker = "",
		prefab_name = "",
		content = "克罗塞尔的离场有些突然。只说了句像是「认证失效了」之类的话，身体忽然融成一滩质地不明的液体，很快连同骸能一起消失了。",
		id = 322271001
	},
	[322271002] = {
		speaker = "我",
		prefab_name = "",
		content = "这家伙……",
		id = 322271002
	},
	[322271003] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "智骸已经有办法跨越时空了吗？",
		id = 322271003
	},
	[322271004] = {
		speaker = "我",
		prefab_name = "",
		content = "哦，那不至于，她应该也是利用往世书过来的。",
		id = 322271004
	},
	[322271005] = {
		speaker = "",
		prefab_name = "",
		content = "怀信显然知道往世书的存在，在我和梵天的说明下，很快理解了构建时空分支以及穿越的原理。",
		id = 322271005
	},
	[322271006] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "是这样……科尔盖开发这种技术，调查历史，想法是好的。",
		id = 322271006
	},
	[322271007] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "但普通分支时空的认证等级太低，调查会遇到许多限制。要是能够修改认证等级的指令，倒是可以帮他们……",
		id = 322271007
	},
	[322271008] = {
		speaker = "",
		prefab_name = "",
		content = "提到这个话题，我又忍不住看向梵天，发现她也是相同的反应。",
		id = 322271008
	},
	[322271009] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这个反应的意思是，你们知道怎么做？",
		id = 322271009
	},
	[322271010] = {
		speaker = "我",
		prefab_name = "",
		content = "失忆以前我可能知道……也只是可能而已。",
		id = 322271010
	},
	[322271011] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "唔，你这一失忆，处处受掣肘啊。",
		id = 322271011
	},
	[322271012] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "可惜，我手里的信息只有这么多，天灾种的问题也帮不上忙。在议会恢复连接之前，只能靠你们自己了。",
		id = 322271012
	},
	[322271013] = {
		speaker = "",
		prefab_name = "",
		content = "已经很有帮助了",
		id = 322271013
	},
	[322271014] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "另外还有一桩事也要麻烦你们。",
		id = 322271014
	},
	[322271015] = {
		speaker = "",
		prefab_name = "",
		content = "怀信伸手指向控制台，基座中央弹出一块数据板。",
		id = 322271015
	},
	[322271016] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "议会断联很匆忙，科尔盖不知情，这些年怕是费了不少心力寻找。",
		id = 322271016
	},
	[322271017] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这块数据板里有断联之前的信息记录，你们帮我交给红狐，一定要是红狐本人。",
		id = 322271017
	},
	[322271018] = {
		speaker = "我",
		prefab_name = "",
		content = "既然你是数据体，我是不是也可以把你带回科尔盖？",
		id = 322271018
	},
	[322271019] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "你倒是敢想。但行不通。",
		id = 322271019
	},
	[322271020] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "与我相关的数据和这里的设备绑定，不能私自转移。",
		id = 322271020
	},
	[322271021] = {
		speaker = "我",
		prefab_name = "",
		content = "什么意思？以后见不到你了？",
		id = 322271021
	},
	[322271022] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "哈哈，纵然天地一逆旅，何必同悲万古尘？",
		id = 322271022
	},
	[322271023] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "何况我只是休眠，如果你们能将议会找回来，还有的是机会叙旧。",
		id = 322271023
	},
	[322271024] = {
		speaker = "我",
		prefab_name = "",
		content = "好吧……传个话而已，一定带到。不过我也有个请求。",
		id = 322271024
	},
	[322271025] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "但说无妨。",
		id = 322271025
	},
	[322271026] = {
		speaker = "我",
		prefab_name = "",
		content = "你知道科尔盖在制造人造修正者吗？",
		id = 322271026
	},
	[322271027] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "近些年的事？这应该是明令禁止的研究，红狐没管么？",
		id = 322271027
	},
	[322271028] = {
		speaker = "我",
		prefab_name = "",
		content = "视骸问题越来越严重，科尔盖急着扩充战斗力，倒不是不能理解……奥丁找科尔盖高层聊过一次，现在好像已经中止了。",
		id = 322271028
	},
	[322271029] = {
		speaker = "我",
		prefab_name = "",
		content = "但有两位人造修正脱离了科尔盖的控制，一直在被追捕，正好我都认识。",
		id = 322271029
	},
	[322271030] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "你希望我命令科尔盖收手？",
		id = 322271030
	},
	[322271031] = {
		speaker = "我",
		prefab_name = "",
		content = "对。我知道只有监察者能指挥奥贝里克。但她们没有任何过错，在夏什瓦特生活也没招惹麻烦。",
		id = 322271031
	},
	[322271032] = {
		speaker = "我",
		prefab_name = "",
		content = "她们有感情，有梦想，和正常的修正者没什么分别。我不希望她们的未来只剩下管制、实验和任务……她们值得更好的生活。",
		id = 322271032
	},
	[322271033] = {
		speaker = "",
		prefab_name = "",
		content = "怀信没说话，只是看着我。直到我心里开始打鼓，他忽然大笑起来，走到我面前，拍了拍我的肩膀。",
		id = 322271033
	},
	[322271034] = {
		speaker = "",
		prefab_name = "",
		content = "尽管投影没有重量，但我依然能感受到他的诚恳与欣慰。",
		id = 322271034
	},
	[322271035] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "果然，失忆归失忆，骨子里的个性不会变。",
		id = 322271035
	},
	[322271036] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "修正者的灵魂不是可以被肆意使用的材料，这事的确是科尔盖过火了，及时制止也在我的责权之内。",
		id = 322271036
	},
	[322271037] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "何况进入盖亚之前，我就是「科技伦理委员会主席」，管这种事，也不是一次两次了。",
		id = 322271037
	},
	[322271038] = {
		speaker = "我",
		prefab_name = "",
		content = "那就多谢了。需要我怎么做？",
		id = 322271038
	},
	[322271039] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "唔……倒不劳你费心。只是不知道你们是否愿意。",
		id = 322271039
	},
	[322271040] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "我有权将她们纳入奥贝里克，这样科尔盖便无权管辖。只要议会指令不出，她们就是自由的。",
		id = 322271040
	},
	[322271041] = {
		speaker = "我",
		prefab_name = "",
		content = "也就是说，如果监察者回归……",
		id = 322271041
	},
	[322271042] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "如果议会当真回归，它们的命令，我们原本也无权拒绝。",
		id = 322271042
	},
	[322271043] = {
		speaker = "",
		prefab_name = "",
		content = "一时找不到更好的办法，我也只能接受这种权宜之计。怀信向我询问了一番诗蔻蒂和洛肯的信息，数据板回到基座内，过了几秒重新弹出来。",
		id = 322271043
	},
	[322271044] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "授权书和身份注册程序都在里面。交给红狐，他会照做。",
		id = 322271044
	},
	[322271045] = {
		speaker = "我",
		prefab_name = "",
		content = "这份人情，将来一定还。",
		id = 322271045
	},
	[322271046] = {
		speaker = "",
		prefab_name = "",
		content = "我抽出数据板，四周墙壁上的照明随之暗了几分，怀信的投影也开始出现不稳定的迹象，但他依旧是一副坦然的姿态，挥手示意我们离开。",
		id = 322271046
	},
	[322271047] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "天灾种事大，你们还是早些回去。",
		id = 322271047
	},
	[322271048] = {
		speaker = "怀信",
		prefab_name = "10149ui_story",
		content = "这里的秘密，记得分寸。",
		id = 322271048
	},
	[322271049] = {
		speaker = "",
		prefab_name = "",
		content = "恍惚之间被送回海滩。恢复清醒时，梵天正坐在我边上，面朝一阵阵后退的海浪，像是两个观海的旅人。",
		id = 322271049
	},
	[322271050] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么坐在这儿发愣？刚才也是，都没怎么说话。",
		id = 322271050
	},
	[322271051] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "……对不起。",
		id = 322271051
	},
	[322271052] = {
		speaker = "我",
		prefab_name = "",
		content = "哈？",
		id = 322271052
	},
	[322271053] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "是我太冲动了嘛，把责任都推到你身上。",
		id = 322271053
	},
	[322271054] = {
		speaker = "我",
		prefab_name = "",
		content = "这……也不用道歉吧。说实话，看到那条记录，我也怀疑自己是不是真的有问题。",
		id = 322271054
	},
	[322271055] = {
		speaker = "我",
		prefab_name = "",
		content = "至于怀信说的那些，别说你了，连我自己都想不到。",
		id = 322271055
	},
	[322271056] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "但我只想着自己的事情就把你……",
		id = 322271056
	},
	[322271057] = {
		speaker = "我",
		prefab_name = "",
		content = "毕竟是准备了这么多年的计划，无论换成谁都不会随便放弃吧？",
		id = 322271057
	},
	[322271058] = {
		speaker = "我",
		prefab_name = "",
		content = "而且，也不能说是冲动，你犹豫了那么久，差点都要哭——",
		id = 322271058
	},
	[322271059] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "才没有，别乱说。",
		id = 322271059
	},
	[322271060] = {
		speaker = "",
		prefab_name = "",
		content = "腰上又被她用力掐了一把，我龇牙咧嘴地跳起来，一边拍打着粘在衣服上的沙子，一边等她起身。",
		id = 322271060
	},
	[322271061] = {
		speaker = "",
		prefab_name = "",
		content = "可她仍旧坐着，似笑非笑地看着我。",
		id = 322271061
	},
	[322271062] = {
		speaker = "我",
		prefab_name = "",
		content = "夏什瓦特需要你。",
		id = 322271062
	},
	[322271063] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "你先回去吧，再给我一点时间。",
		id = 322271063
	},
	[322271064] = {
		speaker = "",
		prefab_name = "",
		content = "梵天变戏法似地掏出一只手套，塞到我口袋里。",
		id = 322271064
	},
	[322271065] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "这个你拿着。传送回去的落点没法精确到弥楼衍。出门在外，总要带点保命的道具。",
		id = 322271065
	},
	[322271066] = {
		speaker = "我",
		prefab_name = "",
		content = "那你呢……你确定还要继续吗？这对你的权能损耗很大，如果不能根除视骸，不值得。",
		id = 322271066
	},
	[322271067] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "值不值得，总得做过才能知道。",
		id = 322271067
	},
	[322271068] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "你相信我能成功吗？",
		id = 322271068
	},
	[322271069] = {
		speaker = "我",
		prefab_name = "",
		content = "我不知道，我能做的只有最后帮你修改「净土」的认证等级。",
		id = 322271069
	},
	[322271070] = {
		speaker = "我",
		prefab_name = "",
		content = "但就像怀信说的……假如你真的已经想好，这就是你拯救盖亚的方式，那就放手去做吧，没人有资格质疑你。",
		id = 322271070
	},
	[322271071] = {
		speaker = "我",
		prefab_name = "",
		content = "如果成功，我们就是新世界的英雄。如果失败……反正早就已经是准备「毁灭世界」的共犯了。",
		id = 322271071
	},
	[322271072] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "为什么你还能这么轻松……这可是跟纪元重启差不多，你认识的所有人，经历过的所有事，都会消失。",
		id = 322271072
	},
	[322271073] = {
		speaker = "我",
		prefab_name = "",
		content = "怎么会轻松呢，我当然也舍不得。可如果因为舍不得就要阻止你，未免太自私了。",
		id = 322271073
	},
	[322271074] = {
		speaker = "我",
		prefab_name = "",
		content = "而且，不单是我……对你来说，不也一样吗？",
		id = 322271074
	},
	[322281001] = {
		speaker = "",
		prefab_name = "",
		content = "许久没有花这么长的时间才入睡，也许久没有在入睡后睡得那么沉。",
		id = 322281001
	},
	[322281002] = {
		speaker = "",
		prefab_name = "",
		content = "冥王……或者说荷鲁斯的归来的确让我无比惊喜，但她口述的拉的事迹又让我忍不住产生了一些复杂的情绪。",
		id = 322281002
	},
	[322281003] = {
		speaker = "",
		prefab_name = "",
		content = "抛开个人感情不谈，三番五次亲眼见过原初修正者强大的我，对拉的实力不会有丝毫质疑。哪怕荷鲁斯继承了生死权能，公正地说，短期内她也不可能替代曾经的拉。",
		id = 322281003
	},
	[322281004] = {
		speaker = "",
		prefab_name = "",
		content = "感性和理性的碰撞就像脑海中一场无疾而终的遭遇战，闹得人辗转反侧，过后又只剩疲惫与一地鸡毛。",
		id = 322281004
	},
	[322281005] = {
		speaker = "吉维卡",
		prefab_name = "10101ui_story",
		content = "……你走神了？",
		id = 322281005
	},
	[322281006] = {
		speaker = "",
		prefab_name = "",
		content = "回过神才忽然意识到自己已经脱离睡梦几个小时了。屏障对面的吉维卡也不知等了多久，小声地提醒了一句，依旧笑盈盈地看着我。",
