	},
	[322281030] = {
		speaker = "",
		prefab_name = "",
		content = "回弥楼衍的路上只有司机帕尔瓦蒂。也许因为她总是懒洋洋的，给人一种像是树洞的安全感，我也就顺道和她聊起了与吉维卡的交谈，以及一些更敏感的内容。",
		id = 322281030
	},
	[322281031] = {
		speaker = "我",
		prefab_name = "",
		content = "我也不想敷衍，可一个失忆的人要怎么回答这种问题……改不改变已经跟我愿不愿意没关系了。",
		id = 322281031
	},
	[322281032] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "找回记忆，会让你变成另一个人吗？",
