	[322281036] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
		content = "谁的生活一成不变呢？虽然我也不讨厌那样……但很多时候不得不挪挪位置，不管是自己爬起来，还是别人推你一把。",
		id = 322281036
	},
	[322281037] = {
		speaker = "帕尔瓦蒂",
		prefab_name = "1089ui_story",
