	[322281092] = {
		speaker = "洛肯",
		prefab_name = "404001ui_story",
		content = "艾因索菲太体面，养不住我这样的闲人。但至少托那位管理员的福，我现在有的选了。",
		id = 322281092
	},
	[322281093] = {
		speaker = "洛肯",
		prefab_name = "404001ui_story",
		content = "「有的选」，已经是人类最大的自由，还有什么比这更让人安心吗？",
		id = 322281093
	},
	[322281094] = {
		speaker = "洛肯",
		prefab_name = "404001ui_story",
		content = "哪天我在夏什瓦特玩儿累了，就来艾因索菲找你们。你要是在艾因索菲不顺心，也可以回来……应该不至于吧。",
		id = 322281094
	},
	[322281095] = {
		speaker = "洛肯",
		prefab_name = "404001ui_story",
		content = "所以，别磨叽了，赶紧下床，跟我练车去。",
		id = 322281095
	},
	[322281096] = {
		speaker = "薇儿丹蒂",
		prefab_name = "10102ui_story",
		content = "管理员……",
		id = 322281096
	},
	[322281097] = {
		speaker = "我",
		prefab_name = "",
		content = "嗯，如果她想来艾因索菲，我肯定不会拒绝。",
		id = 322281097
	},
	[322281098] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "喂，不会真要让她把这辆破车开回深空之眼去吧？",
		id = 322281098
	},
	[322281099] = {
		speaker = "我",
		prefab_name = "",
		content = "不至于，只是给诗蔻蒂代步。梵天，帕瓦，后面就麻烦你们把车还给她了，不然她出门没车也不方便……",
		id = 322281099
	},
	[322281100] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "咦，帕瓦，你原来那辆不是卖给她了吗？",
		id = 322281100
	},
	[322281101] = {
		speaker = "",
		prefab_name = "",
		content = "我这才想起帕尔瓦蒂和洛肯互换座驾的「交易」，见她黑着脸不说话，忍不住笑了笑，在她掏出夏克提之前，开门躲进了车里。",
		id = 322281101
	},
	[322281102] = {
		speaker = "我",
		prefab_name = "",
		content = "走吧走吧，别赶不上光轨了。",
		id = 322281102
	},
	[322281103] = {
