		prefab_name = "1089ui_story",
		content = "能不能自己开……我要把你们带到光轨站，还要开回来，天……",
		id = 322281103
	},
	[322281104] = {
		speaker = "荷鲁斯",
		prefab_name = "1044ui_story",
		content = "你不想开车？那我来好了！",
		id = 322281104
	},
	[322281105] = {
		speaker = "",
		prefab_name = "",
		content = "荷鲁斯大摇大摆地走向驾驶座，我慌忙解开安全带想要阻止她上车，因为我确定她百分百没摸过方向盘。",
		id = 322281105
	},
	[322281106] = {
		speaker = "",
		prefab_name = "",
		content = "但最先拦住她的人并不是我。看到那道娇小的背影，我隐约联想到了一些事情……",
		id = 322281106
	},
	[322281107] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "荷鲁斯，你跟我过来一下。",
		id = 322281107
	},
	[322281108] = {
		speaker = "荷鲁斯",
