		prefab_name = "10131ui_story",
		content = "大家……还好吗？",
		id = 322281143
	},
	[322281144] = {
		speaker = "梵天",
		prefab_name = "1020ui_story",
		content = "你不知道吗？",
		id = 322281144
	},
	[322281145] = {
