	},
	[928011004] = {
		speaker = "",
		prefab_name = "",
		content = "当一切不尽如人意的时候，你是否还会向往未来，并坚定地踏前一步呢？",
		id = 928011004
	},
	[928011005] = {
		speaker = "",
		prefab_name = "",
		content = "车厢沿轨道行驶在半空，城市在脚底喧嚣着，但声量不等触及列车便已消散。",
		id = 928011005
	},
	[928011006] = {
		speaker = "我",
