	},
	[928011011] = {
		speaker = "",
		prefab_name = "",
		content = "诗蔻蒂又转过头去，指尖抵在玻璃窗的倒影上，从她的眼睫开始轻轻划出一条线，直至我的耳侧。",
		id = 928011011
	},
	[928011012] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "每一班空轨，都只在固定的时间，走固定的线路。",
		id = 928011012
	},
	[928011013] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "而且高高地悬在半空中，就这样自己一圈一圈跑着，什么都不能影响它，好像永远不会出错。",
		id = 928011013
	},
	[928011014] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "只要坐上去，就什么都不用担心，很快就能到自己想去的地方。",
		id = 928011014
	},
	[928011015] = {
		speaker = "",
		prefab_name = "",
		content = "列车平稳地转过一座摩天大楼的尖顶，车厢内响起了提醒前方到站的播报声。",
		id = 928011015
	},
	[928011016] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "每一趟都很确定，就像每天的日程表那样，会有安全感。",
		id = 928011016
	},
	[928011017] = {
		speaker = "我",
		prefab_name = "",
		content = "这样，确定性有时候是很让人着迷，不过……",
		id = 928011017
	},
	[928011018] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "不过？",
		id = 928011018
	},
	[928011019] = {
		speaker = "",
		prefab_name = "",
		content = "诗蔻蒂坐正了身子，偏头看着我，一点微微的天蓝色映在她澄澈的粉色眼睛里。",
		id = 928011019
	},
	[928011020] = {
		speaker = "我",
		prefab_name = "",
		content = "……没什么，能一直这样想也很好。",
		id = 928011020
	},
	[928011021] = {
		speaker = "",
		prefab_name = "",
		content = "得到肯定，诗蔻蒂高兴地又向我靠了靠，双脚微微摇晃着。",
		id = 928011021
	},
	[928011022] = {
		speaker = "",
		prefab_name = "",
		content = "到站提示响起，但和我们无关。我们要去的车站还很远——",
		id = 928011022
	},
	[928011023] = {
		speaker = "",
		prefab_name = "",
		content = "仪器稳定运行的声音充盈室内，观测舱里两人平静地闭着眼睛，胸膛微微起伏着，仿佛正在深度睡眠。",
		id = 928011023
	},
	[928011024] = {
		speaker = "",
		prefab_name = "",
		content = "大国主看了一眼监测屏，又对了对终端上的时间，随后在记录中轻快地敲下几个字，把头趴到台子上。",
		id = 928011024
	},
	[928011025] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "正常、正常、还是正常……该不会什么都不发生吧。",
		id = 928011025
	},
	[928011026] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "别太松懈，观测才刚刚开始。按以往的经验来看，这个时间大概还没正式定位到某条世界线。",
		id = 928011026
	},
	[928011027] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "之前已经试了好多办法，这次如果还没反应就头疼了。",
		id = 928011027
	},
	[928011028] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "那就当一次纯粹的移转观测实验也没有问题，升级之后这还是第一次使用。",
		id = 928011028
	},
	[928011029] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "况且按此前的预测，我还是很看好这个方案的。",
		id = 928011029
	},
	[928011030] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "最好行得通，不然诗蔻蒂的问题还要再想新计划……啊，你过来看一眼。",
		id = 928011030
	},
	[928011031] = {
		speaker = "",
		prefab_name = "",
		content = "大国主突然直起身子看向监测屏，微微皱眉。",
		id = 928011031
	},
	[928011032] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "运算量开始下降，这是定位成功了？可是不是太早了一点。",
		id = 928011032
	},
	[928011033] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "不止早，下降的速度也太快了，照这样支撑不到世界线推演完毕的。",
		id = 928011033
	},
	[928011034] = {
		speaker = "",
		prefab_name = "",
		content = "两人对视了一眼，海姆达尔迅速调出对诗蔻蒂的监控数据。",
		id = 928011034
	},
	[928011035] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "我看看……捕捉到了，很微弱的神能波动，但确实存在，应该是被动激发的。",
		id = 928011035
	},
	[928011036] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "这么说我们的想法应该没错，但是……",
		id = 928011036
	},
	[928011037] = {
		speaker = "",
		prefab_name = "",
		content = "话音未落，面前的屏幕上跳出一连串的错误代码，观测异常的警示声也划破了隐科组一贯的平静。",
		id = 928011037
	},
	[928011038] = {
		speaker = "海姆达尔",
		prefab_name = "1033ui_story",
		content = "世界线定位失败了，不知道他们那边卡在什么地方，手动弹出吧。",
		id = 928011038
	},
	[928011039] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "这点数据……下次要想办法让观测持续久一点。",
		id = 928011039
	},
	[928011040] = {
		speaker = "",
		prefab_name = "",
		content = "意识在黑暗中被拽向某个不知名的方向，同此前的每一次观测一样。",
		id = 928011040
	},
	[928011041] = {
		speaker = "",
		prefab_name = "",
		content = "我放平心绪，努力适应着这股拉扯感，等待着意识浮出水面的时刻。",
		id = 928011041
	},
	[928011042] = {
		speaker = "",
		prefab_name = "",
		content = "但拉扯感却在此时戛然而止，紧接着眼前闪过一片白光。",
		id = 928011042
	},
	[928011043] = {
		speaker = "我",
		prefab_name = "",
		content = "到了吗，今天怎么感觉好快？",
		id = 928011043
	},
	[928011044] = {
		speaker = "",
		prefab_name = "",
		content = "但是眼前的景象很快解答了我的问题——至少是这一个问题。",
		id = 928011044
	},
	[928011045] = {
		speaker = "",
		prefab_name = "",
		content = "白色，无边无际的白色没有起点也没有终点向着每一个方向延展，除此之外一无所有。",
		id = 928011045
	},
	[928011046] = {
		speaker = "我",
		prefab_name = "",
		content = "像游戏场景加载失败了一样……也动不了，不如说连角色都没生成。",
		id = 928011046
	},
	[928011047] = {
		speaker = "",
		prefab_name = "",
		content = "一睁开眼我就试着移动了一下，结果根本连身体都没有具现出来，也发不出声音。",
		id = 928011047
	},
	[928011048] = {
		speaker = "我",
		prefab_name = "",
		content = "什么都做不了，只能等大国主她们操作了，希望不是太棘手的情况。",
		id = 928011048
	},
	[928011049] = {
		speaker = "我",
		prefab_name = "",
		content = "倒是诗蔻蒂那边……不知道她遇到了什么状况。",
		id = 928011049
	},
	[928011050] = {
		speaker = "我",
		prefab_name = "",
		content = "她因为想看到我们的未来才答应的，如果也看见这一幕的话……",
		id = 928011050
	},
	[928011051] = {
		speaker = "",
		prefab_name = "",
		content = "这样想着，我叹了口不存在的气，眼前的纯白之中却骤然裂开了一丝细微的缝隙。",
		id = 928011051
	},
	[928011052] = {
		speaker = "",
		prefab_name = "",
		content = "像是被那口气吹碎了一样，那一丝裂缝如蛛网般散射攀缠，终于在几乎爬满了我目所能及的全部空间后，静止了一瞬。",
		id = 928011052
	},
	[928011053] = {
		speaker = "",
		prefab_name = "",
		content = "没有失重感，但是四周骤然崩解时我还是出现了一种自己仿佛漂浮起来的错觉。",
		id = 928011053
	},
	[928011054] = {
		speaker = "",
		prefab_name = "",
		content = "纷飞的碎片缭绕着我，每一片上似乎都能看见隐约的画面，但又很快黯淡消散。",
		id = 928011054
	},
	[928011055] = {
		speaker = "我",
		prefab_name = "",
		content = "这些是……",
		id = 928011055
	},
	[928011056] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "小昙！",
		id = 928011056
	},
	[928011057] = {
		speaker = "",
		prefab_name = "",
		content = "和隐科组屋顶的柔和光线一起出现的，是诗蔻蒂的声音。",
		id = 928011057
	},
	[928011058] = {
		speaker = "",
		prefab_name = "",
		content = "等到视线完全清晰，眼前却挤着三个人头，其中一个就是面带急色的诗蔻蒂。",
		id = 928011058
	},
	[928011059] = {
		speaker = "我",
		prefab_name = "",
		content = "我……躺了很久吗？",
		id = 928011059
	},
	[928011060] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "倒也没有，她只比你早醒一点，但是醒过来就一直站在这儿看着你。",
		id = 928011060
	},
	[928011061] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "刚刚看到的景象，觉得很不安，担心小昙。",
		id = 928011061
	},
	[928011062] = {
		speaker = "我",
		prefab_name = "",
		content = "我没事，就是强制弹出的后遗症似乎要大一点，刚有些晕。",
		id = 928011062
	},
	[928011063] = {
		speaker = "我",
		prefab_name = "",
		content = "比起这个，你说看到了让人不安的景象？",
		id = 928011063
	},
	[928011064] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "嗯，一开始很黑，突然变成白色，最后全部都碎掉了。",
		id = 928011064
	},
	[928011065] = {
		speaker = "诗蔻蒂",
		prefab_name = "1085ui_story",
		content = "哪里都找不到小昙，不知道怎么办才好。",
		id = 928011065
	},
	[928011066] = {
		speaker = "",
		prefab_name = "",
		content = "眩晕感终于彻底消退，我翻身坐直，轻轻按了按额头。",
		id = 928011066
	},
	[928011067] = {
		speaker = "大国主",
		prefab_name = "1066ui_story",
		content = "你这边呢，有看到什么特别的东西吗？",
		id = 928011067
	},
	[928011068] = {
		speaker = "我",
		prefab_name = "",
		content = "大体上应该和她差不多……",
		id = 928011068
	}
}
